insert into public.content (site, kind, id, data, sort, active)
values
  ('chef', 'recipe', 'huevos-rosas-en-escabeche-de-remolacha', '{"n":"Huevos rosas en escabeche de remolacha","pr":"Huevo","sana":"Moderado","dif":"Media","t":35,"val":"⭐⭐⭐⭐⭐","com":"Cuanto más tiempo en el escabeche, más intenso el color: deja unos 2 h y otros toda la noche y tendrás un plato bicolor.","cc":"Comida (entrante)","rac":2,"cong":"No (la clara se vuelve gomosa)","nev":"3","tm":"No","ut":"Cazo pequeño de 1-1,5 L (huevos) · bol grande con agua y hielo · cazo mediano de 1,5-2 L (escabeche) · colador · tarro de cristal o tartera de 1 L con tapa (marinado) · papel de cocina · tabla y cuchillo · cuchara pequeña · bol mediano y tenedor (relleno) · manga pastelera con boquilla rizada (o bolsa de congelación con una esquina cortada) · fuente o plato · temporizador.","ing":[["4","Huevos (talla L)"],["1 ud (~150 g)","Remolacha cocida envasada"],["250 ml","Agua (para el escabeche)"],["50 ml","Vinagre de manzana"],["1 cdita","Azúcar"],["Al gusto","Sal"],["1,5 cda","Mayonesa"],["1,5 cda","Yogur griego natural"],["1 cdita","Mostaza de Dijon"],["1/2 cdita","Vinagre (para el relleno)"],["Al gusto","Perejil o eneldo picado"],["1 cda + 1 pizca","Cebollino picado + pimentón de la Vera"],["30-40 g (opcional)","Salmón ya cocinado, desmigado (sobrante de las recetas de salmón a la naranja o teriyaki)"]],"pasos":["COCER LOS HUEVOS (12 min + 5 de frío): en el cazo pequeño, agua que cubra los huevos 2 cm. Fuego máximo (9 de 9) hasta que hierva. Meter los 4 huevos con una cuchara, uno a uno, bajar a 6 de 9 y contar 10 minutos exactos (los 2 primeros, remover suavemente para que la yema quede centrada). Pasarlos al bol grande con agua y hielo 5 min y pelarlos golpeando la cáscara por todos lados. Están listos cuando la clara está firme y la yema cuajada del todo.","ESCABECHE (12 min + 15 de enfriado): en la tabla, cortar la remolacha en dados de 1 cm. En el cazo mediano: la remolacha, 250 ml de agua, 50 ml de vinagre de manzana, 1 cucharadita de azúcar y una pizca de sal. Fuego máximo (9) hasta que hierva, bajar a 5 de 9 y cocer 10 min. Está listo cuando el líquido es rojo intenso. Dejar enfriar 15 min y colarlo con el colador dentro del tarro (la remolacha se puede comer en ensalada).","MARINAR (mínimo 4 h): meter los huevos pelados en el tarro con el líquido ya frío; tienen que quedar cubiertos del todo. Tapar y a la nevera al menos 4 h (mejor toda la noche). Si no quedan cubiertos, darles la vuelta a mitad de tiempo.","PARTIR (3 min): sacar los huevos del tarro, secarlos con papel de cocina, partirlos a lo largo en la tabla con el cuchillo y sacar las yemas con la cuchara pequeña al bol mediano. Colocar las 8 mitades de clara en la fuente.","RELLENO (3 min): en el bol mediano, chafar las yemas con el tenedor y añadir 1,5 cucharadas de mayonesa, 1,5 de yogur griego, 1 cucharadita de mostaza, 1/2 cucharadita de vinagre, el perejil o eneldo picado y una pizca de sal. Remover 1 minuto. Está listo cuando es una crema lisa, sin grumos.","RELLENAR (3 min): meter la crema en la manga pastelera y rellenar las 8 mitades de clara que están en la fuente, haciendo una espiral.","TERMINAR Y SERVIR: en la tabla, picar fino el cebollino (1 cucharada). Ponerlo por encima con una pizca de pimentón de la Vera y, si hay, 30-40 g de migas de salmón ya cocinado. Servir frío (o tapar la fuente y a la nevera; ver Notas)."],"foto":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/20/Pickled_beet_eggs_large.jpg/330px-Pickled_beet_eggs_large.jpg"}'::jsonb, 1, true),
  ('chef', 'recipe', 'huevos-rellenos-de-hummus-zanahoria-y-pepino', '{"n":"Huevos rellenos de hummus, zanahoria y pepino","pr":"Huevo","sana":"Sí","dif":"Fácil","t":25,"val":"","com":"Variante: cambia el pimentón del hummus por comino o curry. Rellénalos justo antes de comer para que la verdura siga crujiente.","cc":"Cena","rac":2,"cong":"No","nev":"2","tm":"Sí","ut":"Cazo pequeño de 1-1,5 L (huevos) · bol grande con agua fría · colador (garbanzos) · tabla y cuchillo · cuchara pequeña · batidora de brazo con su vaso alto (hummus) · exprimidor · pelador · rallador (lado grueso) · bol mediano y cuchara (mezcla) · fuente o plato llano · temporizador. Versión TM5: Thermomix TM5 con vaso, tapa, cubilete, cestillo y espátula.","ing":[["4","Huevos"],["200 g","Garbanzos cocidos (medio bote de 400 g), escurridos"],["1 cda","Tahini (pasta de sésamo)"],["1/2 diente","Ajo"],["1/2 limón","Zumo de limón"],["1 cdita","Pimentón (dulce o de la Vera ahumado)"],["1","Zanahoria"],["1/2","Pepino"],["1 puñado","Canónigos"],["1-2 cda","Aceite de oliva virgen extra"],["1-2 cda","Agua (si el hummus queda espeso)"],["Al gusto","Sal"]],"pasos":["COCER LOS HUEVOS (12 min + 5 de frío): en el cazo pequeño, agua que cubra los huevos 2 cm y una pizca de sal. Fuego máximo (9 de 9) hasta que hierva. Meter los 4 huevos con una cuchara, bajar a 6 de 9 y contar 10 minutos exactos. Pasarlos al bol grande con agua fría 5 min y pelarlos. Están listos cuando la yema está cuajada del todo.","PARTIR (2 min): en la tabla, partir los huevos a lo largo con el cuchillo; sacar las yemas con la cuchara pequeña al bol mediano y colocar las 8 claras en la fuente.","HUMMUS (3 min): escurrir y enjuagar 200 g de garbanzos en el colador. En el vaso alto de la batidora: los garbanzos, 1 cucharada de tahini, 1/2 diente de ajo pelado, el zumo de 1/2 limón (con el exprimidor), una pizca de sal, 1/2 cucharadita de pimentón y 1 cucharada de aceite. Triturar 1 minuto; si queda espeso, añadir 1-2 cucharadas de agua y 30 segundos más. Está listo cuando es una crema lisa que cae despacio de la cuchara.","VERDURA (4 min): pelar la zanahoria con el pelador y rallarla con el lado grueso del rallador. En la tabla, cortar medio pepino en dados de medio centímetro.","MEZCLA (2 min): en el bol mediano, chafar las yemas con la cuchara, añadir el hummus, la zanahoria y el pepino y mezclar 1 minuto.","RELLENAR (3 min): con la cuchara, rellenar las 8 claras de la fuente formando una montañita.","SERVIR: espolvorear el resto del pimentón (1/2 cucharadita) y un hilo de aceite. Poner al lado de la fuente un puñado de canónigos aliñados con 1 cucharada de aceite y una pizca de sal."],"foto":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/c4/Deviled_Eggs_topped_with_Scallions.JPG/330px-Deviled_Eggs_topped_with_Scallions.JPG"}'::jsonb, 2, true),
  ('chef', 'recipe', 'salmon-al-vapor-con-salsa-de-naranja-y-patatas', '{"n":"Salmón al vapor con salsa de naranja y patatas","pr":"Salmón","sana":"Sí","dif":"Fácil","t":35,"val":"","com":"Si el lomo es fino, sácalo 1 minuto antes: la salsa caliente termina de hacerlo. También queda muy bien con boniato en lugar de patata.","cc":"Comida","rac":2,"cong":"No (la patata cocida se estropea)","nev":"2","tm":"Sí","ut":"Plato hondo (descongelar) · papel de cocina · tabla y cuchillo · pelador · olla mediana de 3 L (patatas) · colador · sartén pequeña de 20 cm (salsa) · exprimidor · sartén antiadherente de 24-28 cm (salmón) · espátula · cuchara · 2 platos · termómetro de cocina · temporizador. Versión TM5: Thermomix TM5 con vaso, tapa, cubilete, espátula y Varoma (recipiente y bandeja).","ing":[["2 lomos (1 paquete de 250 g)","Salmón congelado en lomos (Poseidón, Ahorramás)"],["350 g","Patatas cortadas en rodajas finas"],["60 g","Cebolla"],["15 g","Aceite de oliva virgen extra (y un poco para pincelar)"],["100 g","Zumo de naranja natural (1-2 naranjas)"],["30 g","Agua"],["15 g","Miel"],["Al gusto","Sal y pimienta negra"]],"pasos":["DESCONGELAR (la víspera): pasar los 2 lomos del congelador al plato hondo, tapados, y a la nevera unas 12 h. Antes de cocinar, secarlos bien con papel de cocina.","PATATAS (15-18 min): pelar 350 g de patatas con el pelador y cortarlas en la tabla en rodajas de medio centímetro. En la olla mediana, agua que las cubra y 1 cucharadita de sal; fuego máximo (9 de 9) hasta que hierva. Añadir las patatas, bajar a 6 de 9 y cocer 12-15 min. Están listas cuando la punta del cuchillo entra sin resistencia. Escurrirlas en el colador.","SOFRITO (6 min): en la tabla, picar 60 g de cebolla en daditos de medio centímetro. En la sartén pequeña, 15 g de aceite a fuego medio-bajo (4 de 9) y esperar 1 min. Añadir la cebolla y remover cada minuto durante 5 min. Está lista cuando está transparente y blanda, sin dorarse.","SALSA (5 min): exprimir 1-2 naranjas con el exprimidor hasta tener 100 g de zumo. Añadir a la sartén pequeña el zumo, 30 g de agua, 15 g de miel, sal y pimienta. Subir a 6 de 9 y dejar reducir 4-5 min. Está lista cuando cubre («napa») el dorso de la cuchara, como un almíbar ligero.","SALMÓN (6-7 min): en la sartén antiadherente, unas gotas de aceite a fuego medio-alto (7 de 9) y esperar 1 min. Salpimentar los lomos y ponerlos con la piel hacia abajo 3-4 min sin moverlos; darles la vuelta con la espátula y 2-3 min más. Está listo cuando por fuera está opaco y al presionar el centro se separa en láminas (punto jugoso). TEMPERATURA: sin sacarlo de la sartén antiadherente, pinchar el termómetro de cocina por el lateral del lomo hasta el centro de la parte más gruesa, sin tocar la sartén, y esperar unos segundos a que la cifra se estabilice: tiene que marcar 63 °C. Si no llega, seguir 2 minutos más a fuego 5 de 9 y volver a medir.","EMPLATAR: en cada plato, una base de patatas, el lomo encima y 2-3 cucharadas de salsa de la sartén pequeña por encima. Opcional: un poco de ralladura de naranja."],"foto":"https://upload.wikimedia.org/wikipedia/commons/thumb/d/de/DFC_1189_Pan-seared_salmon_fillet_served_with_creamy_mashed_potatoes_a_lime_wedge_and_a_side_of_sauce.jpg/330px-DFC_1189_Pan-seared_salmon_fillet_served_with_creamy_mashed_potatoes_a_lime_wedge_and_a_side_of_sauce.jpg"}'::jsonb, 3, true),
  ('chef', 'recipe', 'salmon-teriyaki-con-arroz-basmati-y-brocoli', '{"n":"Salmón teriyaki con arroz basmati y brócoli","pr":"Salmón","sana":"Sí","dif":"Fácil","t":35,"val":"","com":"Al cocinar para congelar, deja el brócoli un punto al dente: al recalentar termina de hacerse y no se queda blando.","cc":"Comida","rac":4,"cong":"Sí","nev":"2","tm":"No","ut":"Plato hondo (descongelar) · tabla y cuchillo · rallador fino (jengibre) · exprimidor · cazo de 1-1,5 L (salsa) · bol mediano (marinar) · colador · olla grande de 4 L (arroz) · olla mediana de 3 L con tapa y cestillo de vapor (brócoli) · sartén grande de 28 cm · espátula · plato llano (reservar el salmón) · 2 platos · 2 tarteras herméticas aptas para congelador · termómetro de cocina · temporizador.","ing":[["4 lomos (2 paquetes de 250 g)","Salmón congelado en lomos (Poseidón, Ahorramás)"],["320 g","Arroz basmati"],["400 g","Brócoli en ramilletes"],["120 ml","Salsa de soja (mejor baja en sal)"],["60 ml","Miel"],["60 ml","Zumo de limón"],["120 ml","Agua"],["4 cm","Jengibre fresco"],["2 cditas","Sésamo tostado"],["Al gusto","Cilantro o cebolleta picada"],["2 chorritos","Aceite de oliva virgen extra"],["Al gusto","Sal y pimienta"],["Opcional","Jengibre encurtido para decorar"]],"pasos":["DESCONGELAR (la víspera): pasar los 4 lomos al plato hondo, tapados, y a la nevera unas 12 h. En la tabla, quitarles la piel con el cuchillo y cortarlos en dados de unos 3 cm.","SALSA (5 min): en el cazo: 120 ml de soja, 60 ml de miel, 120 ml de agua, 60 ml de zumo de limón (con el exprimidor) y 4 cm de jengibre pelado y rallado con el rallador fino. Fuego máximo (9 de 9) hasta que hierva, bajar a 5 de 9 y cocer 4 min. Retirar y dejar templar.","MARINAR (10 min): en el bol mediano, los dados de salmón con 4 cucharadas de la salsa; remover y dejar 10 min. Mientras, el resto de la salsa sigue en el cazo a fuego 5 de 9 otros 4-5 min. Está lista cuando cubre («napa») el dorso de la cuchara.","ARROZ (10 min de hervor + 12 de cocción): lavar 320 g de arroz en el colador bajo el grifo 45 segundos. En la olla grande, 2,5 L de agua y 2 cucharaditas de sal a fuego máximo (9) hasta que hierva. Echar el arroz, remover una vez, bajar a 6 de 9 y cocer 12 min sin tapa. Está listo cuando el grano está tierno pero entero. Escurrirlo en el colador.","BRÓCOLI (5 min): en la tabla, cortar 400 g de brócoli en ramilletes de 3-4 cm. En la olla mediana, 3 dedos de agua a fuego máximo (9); cuando hierva, poner el brócoli en el cestillo de vapor dentro de la olla, tapar y cocer 5 min. Está listo cuando es verde intenso y el tenedor entra con un poco de resistencia.","SALMÓN EN 2 TANDAS (8-9 min): en la sartén grande, un chorrito de aceite a fuego fuerte (8 de 9) y esperar 1 min. Echar la mitad del salmón escurrido y dorarlo 3-4 min por todos lados sin amontonarlo; pasarlo al plato llano. Repetir con la otra mitad. Volver a poner todo en la sartén, verter la salsa reducida del cazo y remover 30 segundos a fuego 5. Está listo cuando está dorado, brillante y se separa en láminas. TEMPERATURA: en la sartén grande (antes de añadir la salsa en la segunda tanda), pinchar el termómetro de cocina en el centro del dado de salmón más grueso, sin tocar la sartén, y esperar unos segundos a que la cifra se estabilice: tiene que marcar 63 °C. Si no llega, seguir 2 minutos más y volver a medir.","SERVIR 2 RACIONES: en los 2 platos, arroz, brócoli al lado y salmón con salsa por encima; terminar con sésamo, cilantro o cebolleta (y jengibre encurtido si se quiere).","LAS OTRAS 2 RACIONES: repartir arroz, brócoli y salmón con su salsa en las 2 tarteras, dejarlas templar destapadas (como mucho 1 h fuera de la nevera), taparlas y a la nevera o al congelador (ver Notas)."],"foto":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/95/Grilled_Teriyaki_Salmon_%2810900376705%29.jpg/330px-Grilled_Teriyaki_Salmon_%2810900376705%29.jpg"}'::jsonb, 4, true),
  ('chef', 'recipe', 'crema-de-calabacin-y-puerro-con-huevo-poche', '{"n":"Crema de calabacín y puerro con huevo poché","pr":"Calabacín","sana":"Sí","dif":"Fácil","t":35,"val":"","com":"Si al descongelarla queda algo aguada, dale un hervor de 2 minutos sin tapa. Variante: un puñado de espinacas al triturar.","cc":"Cena","rac":4,"cong":"Sí (solo la crema; el huevo poché se hace al servir)","nev":"3","tm":"Sí","ut":"Tabla y cuchillo · pelador · olla grande de 4-5 L con tapa · batidora de brazo · cazo pequeño de 1,5 L (para el poché) · taza pequeña (para cascar el huevo) · cuchara · espumadera · papel de cocina · taza medidora · cuchara sopera · cuencos · 2 tarteras herméticas aptas para congelador · termómetro de cocina · temporizador. Versión TM5: Thermomix TM5 con vaso, tapa, cubilete y espátula (y un trapo para sujetar el cubilete al triturar).","ing":[["4 medianos (unos 1 kg)","Calabacín, con piel"],["2 (unos 300 g)","Puerro (solo la parte blanca y verde clara)"],["2 medianas (unos 300 g)","Patata"],["1 litro","Agua"],["2 pastillas o 2 cditas rasas (10 g)","Caldo de verduras en pastilla, o sal"],["2 (opcional)","Quesito en porción (light si hay), para que quede más cremosa"],["2 cdas (20 g) + un hilo al servir","Aceite de oliva virgen extra"],["4 (1 por ración; se hacen al servir, nunca se congelan)","Huevos (los más frescos que tengáis)"],["1 cda (15 ml)","Vinagre (para el agua del poché)"],["Al gusto","Pimienta negra y una pizca de pimentón"]],"pasos":["PREPARAR VERDURAS (8 min, en la tabla con el cuchillo y el pelador): lavar los 4 calabacines, quitar las dos puntas y cortarlos en rodajas de 1 cm (con piel). Puerros: cortar la raíz y la parte verde oscura, abrirlos a lo largo, lavarlos bajo el grifo separando las capas (suelen tener tierra) y cortarlos en rodajas de 1 cm. Patatas: pelarlas y cortarlas en dados de unos 2 cm.","SOFRITO (8 min): olla GRANDE de 4-5 L a fuego medio (5 de 9) con 2 cucharadas de aceite; esperar 2 min a que se caliente. Añadir el puerro y remover cada minuto durante 6 min. Está listo cuando está blando y transparente, sin llegar a dorarse (si se dora, bajar a 4).","COCER (8 + 15-18 min): en la misma olla grande, añadir el calabacín, la patata, el litro de agua (medido con la taza medidora) y las 2 pastillas de caldo (o la sal). Subir a fuego máximo (9) hasta que hierva con burbujas grandes (unos 8 min, tarda más que con media cantidad). Bajar a fuego medio-bajo (4 de 9), tapar y cocer 15-18 min. Está lista cuando un trozo de patata se deshace al pincharlo con un tenedor.","TRITURAR (12 min): apagar el fuego y dejar templar 10 min (sin tapa). Añadir los quesitos y triturar con la batidora de brazo unos 3 min, moviendo por toda la olla, hasta que no quede ningún grumo. Probar y añadir sal si hace falta. Si está muy espesa, añadir 100 ml de agua y batir otra vez. Apartar ahora las 2 raciones para congelar (ver Notas) y dejar el resto en la olla tapada.","AGUA DEL POCHÉ (6 min, se puede hacer mientras cuece la crema): en un cazo pequeño poner 1 litro de agua y 1 cucharada de vinagre, sin sal. Fuego máximo (9) hasta que hierva. Bajar a fuego medio (4-5 de 9): el agua debe moverse con burbujitas pequeñas, sin borbotones.","POCHÉ (3-4 min por huevo; solo los de las raciones que se sirven ahora, normalmente 2): cascar un huevo en una taza pequeña. Con una cuchara, remover el agua en círculo para hacer un remolino y, en el centro, dejar caer el huevo despacio desde la taza. No tocarlo. 3 min exactos = yema líquida; 4 min = yema medio cuajada. Está listo cuando la clara está toda blanca (nada transparente) y la yema tiembla al mover el cazo.","SACAR: con una espumadera, sacar el huevo y dejarlo 10 segundos sobre papel de cocina para que escurra. Repetir con el siguiente huevo (si el cazo es ancho, pueden hacerse dos a la vez en lados distintos; para 4 raciones a la vez, en 2 tandas).","SERVIR: repartir la crema en cuencos (unos 350 ml cada uno), poner el huevo poché en el centro, un hilo de aceite, pimienta y una pizca de pimentón. Se rompe la yema al comer y se mezcla con la crema."],"foto":"https://upload.wikimedia.org/wikipedia/commons/thumb/7/7c/Zucchini_soup.JPG/330px-Zucchini_soup.JPG"}'::jsonb, 5, true),
  ('chef', 'recipe', 'bowl-templado-de-basmati-brocoli-huevo-y-salsa-de-yogur-y-limon', '{"n":"Bowl templado de basmati, brócoli, huevo y salsa de yogur y limón","pr":"Arroz basmati","sana":"Sí","dif":"Fácil","t":20,"val":"","com":"Variante: huevo a la plancha en lugar de cocido o unos garbanzos tostados por encima. Monta el bowl justo antes de comer.","cc":"Comida","rac":2,"cong":"No","nev":"1","tm":"No","ut":"Olla mediana de 2-3 L con tapa · colador · cazo pequeño de 1-1,5 L (huevos) · bol con agua fría · tabla y cuchillo · pelador · rallador (lado grueso para la zanahoria, lado fino para la piel del limón) · exprimidor o tenedor · bol pequeño y tenedor (salsa) · cuchara · 2 cuencos · termómetro de cocina · temporizador.","ing":[["150 g","Arroz basmati"],["1 litro + 1 cdita (5 g) de sal","Agua para cocer el arroz y el brócoli"],["250 g (1 cabeza pequeña)","Brócoli"],["4","Huevos"],["1 (unos 80 g)","Zanahoria"],["1/2 (unos 100 g)","Pepino"],["1 (125 g)","Yogur natural (o griego) sin azúcar"],["1/2","Limón (ralladura y zumo)"],["1 cdita (5 ml) + un hilo","Aceite de oliva virgen extra"],["1 pizca","Sal (para la salsa)"],["1 pizca","Pimentón (dulce o de la Vera) o perejil picado"]],"pasos":["HERVIR EL AGUA (6-8 min): en una olla mediana poner 1 litro de agua y 1 cucharadita de sal. Tapar y poner a fuego máximo (9 de 9) hasta que hierva con burbujas grandes.","PREPARAR MIENTRAS HIERVE (5 min): en la tabla, cortar el brócoli en ramilletes pequeños, de unos 3-4 cm (el tronco grueso, pelado y en rodajas de medio cm). Lavar el arroz en el colador bajo el grifo 30 segundos, moviendo con la mano, hasta que el agua salga menos turbia.","ARROZ (11 min): echar el arroz en la olla mediana con el agua hirviendo, remover una vez con la cuchara para que no se pegue, quitar la tapa y bajar a fuego medio-alto (6 de 9). Poner el temporizador en 11 minutos.","HUEVOS (9 min + 3 min de frío): a la vez, en el cazo pequeño con agua que cubra los huevos 2 cm, fuego máximo (9) hasta que hierva. Meter los 4 huevos con la cuchara, uno a uno, bajar a 6 de 9 y contar 9 minutos exactos (yema cuajada pero jugosa). Pasarlos al bol con agua fría del grifo 3 min, pelarlos golpeando la cáscara por todos lados y cortarlos en cuartos a lo largo en la tabla.","BRÓCOLI EN LA MISMA OLLA: cuando al arroz le queden 4 minutos (minuto 7 del temporizador), echar el brócoli en la olla del arroz. Al acabar los 11 min, probar un grano: tiene que estar tierno pero entero. El brócoli debe estar verde intenso y pincharse fácil con un tenedor. Escurrir todo junto en el colador.","VERDURA CRUDA (3 min): pelar la zanahoria con el pelador y rallarla con el lado de agujero grueso del rallador. En la tabla, lavar el pepino (con piel) y cortarlo en dados de 1 cm.","SALSA (2 min): en el bol pequeño, poner el yogur, la ralladura de medio limón (con el lado fino del rallador; solo la piel amarilla, sin lo blanco, que amarga), el zumo de medio limón (con el exprimidor; aprox. 1 cucharada y media), una pizca de sal y 1 cucharadita de aceite. Remover con el tenedor 30 segundos hasta que esté lisa.","MONTAR: repartir el arroz con brócoli en 2 cuencos. A un lado, la zanahoria rallada y el pepino. Encima, 2 huevos en cuartos por persona. Repartir la salsa por encima (unas 3 cucharadas por cuenco), un hilo de aceite y una pizca de pimentón. Se come templado."],"foto":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/55/Healthy_Vegan_Buddha_Bowl_-_49859044753.jpg/330px-Healthy_Vegan_Buddha_Bowl_-_49859044753.jpg"}'::jsonb, 6, true),
  ('chef', 'recipe', 'tosta-de-hummus-con-huevo-pepino-y-zanahoria', '{"n":"Tosta de hummus con huevo, pepino y zanahoria","pr":"Huevo","sana":"Sí","dif":"Fácil","t":15,"val":"","com":"Frota el pan recién tostado con medio diente de ajo antes de untar el hummus: más sabor sin gastar más.","cc":"Cena","rac":2,"cong":"No","nev":"0 (al momento; hummus, huevo y verdura por separado: 2 días)","tm":"No","ut":"Cazo pequeño de 1-1,5 L · cuchara · bol con agua fría · tabla · cuchillo de sierra (pan) y cuchillo normal · pelador · rallador (lado grueso) · sartén de 24-28 cm o tostadora · espátula o pinzas · cuchillo de untar · cuchara sopera · temporizador.","ing":[["4 rebanadas de 1,5 cm (unos 40 g cada una)","Pan de barra o pan rústico (mejor que pan de molde)"],["120 g (unas 8 cucharadas)","Hummus (el que sobre de los huevos de hummus, o una tarrina del súper)"],["4","Huevos"],["1/2 (unos 100 g)","Pepino"],["1 (unos 80 g)","Zanahoria"],["1 cdita","Sésamo o una pizca de pimentón de la Vera"],["4 cditas (1 por tosta)","Aceite de oliva virgen extra"],["Al gusto","Sal y pimienta negra"]],"pasos":["HERVIR AGUA (5 min): en el cazo pequeño de 1-1,5 L, agua suficiente para que cubra los huevos 2 cm. Fuego máximo (9 de 9) hasta que hierva con burbujas grandes. Mientras, preparar el bol con agua fría del grifo.","COCER LOS HUEVOS (8 min): meter los 4 huevos en el cazo con la cuchara, uno a uno, para que no se rompan. Bajar a fuego medio-alto (6 de 9) y poner el temporizador: 8 minutos exactos = yema cremosa (como en la fuente); 10 minutos = yema totalmente cuajada.","ENFRIAR Y PELAR (3 min): pasar los huevos al bol de agua fría y dejarlos 3 min. Golpearlos por todos lados contra la encimera y pelarlos bajo el grifo. En la tabla, cortarlos con el cuchillo normal en rodajas de medio centímetro (o en cuartos).","VERDURA (mientras cuecen los huevos, 3 min): en la tabla, lavar el pepino y cortarlo con piel en rodajas de medio centímetro (salen unas 12) con el cuchillo normal. Pelar la zanahoria con el pelador y rallarla con el lado de agujero grueso del rallador.","TOSTAR EL PAN (5 min): cortar las 4 rebanadas de 1,5 cm en la tabla con el cuchillo de sierra. Sartén de 24-28 cm sin aceite a fuego medio-alto (7 de 9), calentar 1 min. Poner las rebanadas y tostarlas 2 min por cada lado, dándoles la vuelta con la espátula o las pinzas. Están listas cuando están doradas y crujientes por fuera (si se oscurecen antes, bajar a 6). También vale la tostadora, 2-3 min.","UNTAR: con la cuchara sopera y el cuchillo de untar, extender en cada tosta 30 g de hummus (2 cucharadas colmadas), llegando hasta los bordes.","MONTAR: encima del hummus, 3 rodajas de pepino, un puñadito de zanahoria rallada y las rodajas de 1 huevo por tosta.","TERMINAR Y SERVIR: una pizca de sal y pimienta sobre el huevo, el sésamo o el pimentón y 1 cucharadita de aceite por tosta. Servir enseguida para que el pan no se ablande (2 tostas por persona)."],"foto":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/4c/Smoky_Houmous_on_Toast_-_The_Shed_2025-07-26.jpg/330px-Smoky_Houmous_on_Toast_-_The_Shed_2025-07-26.jpg"}'::jsonb, 7, true),
  ('chef', 'recipe', 'arroz-tres-delicias-casero-huevo-zanahoria-guisantes-y-jamon', '{"n":"Arroz tres delicias casero (huevo, zanahoria, guisantes y jamón)","pr":"Arroz basmati","sana":"Sí","dif":"Fácil","t":25,"val":"","com":"Un hilo de aceite de sésamo al final le da el toque de restaurante. Saltea siempre a fuego fuerte y sin tapar.","cc":"Cena","rac":4,"cong":"Sí","nev":"1","tm":"No","ut":"Colador · olla grande de 4 L con tapa · 2 bandejas o platos grandes (para enfriar el arroz) · cazo de 1,5-2 L · bol y tenedor (batir huevos) · plato (reservar el huevo) · sartén grande de 28 cm o wok · espátula · fuente de servir · tabla y cuchillo · pelador · cuchara sopera (para medir) · 2 tarteras herméticas aptas para congelador · termómetro de cocina · temporizador (el móvil vale).","ing":[["300 g en crudo (unos 800 g ya cocido)","Arroz basmati (o el que sobre del bowl de basmati, ya cocido y frío)"],["2 litros + 2 cditas (10 g) de sal","Agua para cocer el arroz (cocción en agua abundante, proporción aprox. 1:7, y se escurre)"],["4","Huevos"],["2 (unos 160 g)","Zanahoria"],["100 g (4 puñados)","Guisantes congelados"],["120 g","Jamón cocido en taquitos (o 2 lonchas gruesas cortadas en dados de 1 cm)"],["1 litro","Agua para cocer zanahoria y guisantes"],["50 ml (20 + 15 + 15 ml; unas 10 cucharaditas)","Aceite de girasol o de oliva suave"],["30 ml (2 cucharadas)","Salsa de soja"],["2 tallos (opcional)","Cebolleta (solo la parte verde) o cebollino"],["2 pizcas","Sal (para los huevos)"]],"pasos":["ARROZ (si no hay arroz cocido del día anterior; 25 min): poner los 300 g de arroz en el colador y lavarlo bajo el grifo 45 segundos, moviendo con la mano, hasta que el agua salga casi clara. En la olla grande de 4 L, 2 litros de agua con 2 cucharaditas de sal; tapar y fuego máximo (9 de 9) hasta que hierva con burbujas grandes (10-12 min). Echar el arroz, remover una vez, quitar la tapa y bajar a 6 de 9. Cocer 11 minutos exactos. Está listo cuando un grano está tierno pero entero. Escurrir en el colador.","ENFRIAR EL ARROZ (40 min, la clave para que quede suelto): extenderlo en 2 bandejas o platos grandes, en capa fina, sin tapar. Dejarlo 10 min en la encimera y luego 30 min en la nevera, sin tapa (o en tarteras toda la noche). Nunca más de 1 hora fuera de la nevera. Está listo cuando al tocarlo los granos están fríos, secos y se separan solos con los dedos. Antes de usarlo, deshacer los grumos con las manos.","ZANAHORIA Y GUISANTES (10 min): en la tabla, pelar las 2 zanahorias con el pelador y cortarlas en dados de medio centímetro (rodajas de 0,5 cm, luego tiras y luego dados). En el cazo de 1,5-2 L, 1 litro de agua a fuego máximo (9) hasta que hierva. Echar la zanahoria y los 100 g de guisantes (congelados, tal cual) y cocer 4 minutos exactos desde que vuelva a hervir. Escurrir en el colador. Están listos cuando la zanahoria se pincha con un tenedor pero sigue firme.","HUEVO (3 min): en el bol, batir los 4 huevos con 2 pizcas de sal 30 segundos con el tenedor. En la sartén grande, 20 ml de aceite (4 cucharaditas) a fuego medio (5 de 9) y esperar 1 min. Verter el huevo, dejarlo quieto 45 segundos y luego remover con la espátula 45 segundos más. Está listo cuando está cuajado pero todavía brillante, sin dorarse. Sacarlo al plato y trocearlo con la espátula en trozos de 1 cm.","SALTEAR EN 2 TANDAS (la sartén de 28 cm no admite 800 g de arroz de una vez: si se amontona, se cuece en vez de saltearse). TANDA 1, BASE (3 min): en la misma sartén (sin lavar), 15 ml de aceite (1 cucharada) a fuego fuerte (8 de 9) y esperar 1 min hasta que esté muy caliente. Añadir la MITAD de la zanahoria, los guisantes y el jamón y saltear 2 minutos removiendo sin parar.","TANDA 1, ARROZ (4 min): añadir la MITAD del arroz frío y repartirlo por la sartén. Remover sin parar 4 minutos exactos con el fuego en 8 de 9. Tiene que chisporrotear («sonar»). Está listo cuando los granos están sueltos, calientes y algunos un poco tostados. Si se pega mucho, bajar a 7.","TANDA 1, REMATAR (1 min): añadir la mitad del huevo troceado y 1 cucharada (15 ml) de salsa de soja repartida por encima. Saltear 1 minuto más y pasar a una fuente. REPETIR los pasos 5 a 7 con la TANDA 2 (otros 15 ml de aceite, el resto de ingredientes y la otra cucharada de soja). Probar: normalmente no hace falta sal porque la soja ya sala. La soja va siempre al final para que no se queme.","SERVIR (sin reposo): espolvorear la cebolleta picada fina y servir enseguida 2 platos. No tapar la fuente: el vapor humedece el arroz. Las otras 2 raciones, enfriarlas rápido extendidas en una tartera plana y a la nevera o al congelador antes de 1 hora (ver Notas)."],"foto":"https://upload.wikimedia.org/wikipedia/commons/thumb/f/f6/Arroz_tres_delicias.jpg/330px-Arroz_tres_delicias.jpg"}'::jsonb, 8, true),
  ('chef', 'recipe', 'arroz-caldoso-de-pollo-y-verduras', '{"n":"Arroz caldoso de pollo y verduras","pr":"Arroz redondo","sana":"Sí","dif":"Fácil","t":45,"val":"","com":"Variante de temporada: añade alcachofa o judías verdes con el sofrito. Mejor recién hecho: el arroz caldoso no espera.","cc":"Comida","rac":2,"cong":"No (el arroz se pasa)","nev":"1","tm":"Sí","ut":"Tabla y cuchillo · pelador · cazuela baja u olla mediana de 2-3 L (unos 24 cm) con tapa · cazo para calentar el caldo · cuchara de madera · taza medidora (o báscula) · cucharas sopera y de postre (para medir) · termómetro de cocina · temporizador. Versión TM5: Thermomix TM5 con vaso, tapa, cubilete, cestillo (como tapa antisalpicaduras) y espátula.","ing":[["100 g","Arroz redondo (tipo bomba o normal); NO se lava"],["450 ml al fuego / 325 g en TM5","Caldo de pollo (o agua + 1/2 pastilla de caldo de pollo). Proporción arroz:caldo = 1:4,5 al fuego (se evapora más) y 1:3,25 en TM5"],["150 g","Contramuslos de pollo sin piel ni hueso"],["50 g (1/2 cebolla pequeña)","Cebolla"],["50 g (1/2 pimiento)","Pimiento verde o rojo"],["50 g (1/2 zanahoria)","Zanahoria"],["1 pequeño","Diente de ajo"],["75 g","Brócoli en ramilletes pequeños (el que sobre del bowl o del teriyaki)"],["50 g","Guisantes congelados"],["20 g (2 cucharadas)","Aceite de oliva virgen extra"],["1/2 cucharada","Tomate frito"],["1 pizca de cada","Tomillo y romero secos (o 1 hoja de laurel)"],["4 hebras o 1/2 cdita","Azafrán, o pimentón dulce (más barato) + 1/2 cdita de sal"]],"pasos":["CORTAR (8 min, en la tabla con el cuchillo y el pelador): pelar y picar el ajo muy fino. Cebolla en dados de medio centímetro. Pimiento y zanahoria (pelada) en dados de 1 cm. Pollo en dados de 2-3 cm con una pizca de sal. Brócoli en ramilletes de 2-3 cm.","CALDO CALIENTE: medir 450 ml de caldo con la taza medidora y ponerlo en el cazo a fuego 4 de 9 para que esté caliente (sin hervir fuerte) cuando haga falta. Si se usa pastilla, disolver 1/2 pastilla en 450 ml de agua en el cazo.","SOFRITO (11 min): en la cazuela de unos 24 cm, 2 cucharadas de aceite a fuego medio (5 de 9) y esperar 1 min. Añadir cebolla, pimiento, zanahoria y ajo y cocinar 10 minutos removiendo cada 2 min con la cuchara de madera. Está listo cuando la cebolla está transparente y blanda y el pimiento tierno, sin quemarse (si se dora mucho, bajar a 4).","POLLO (4 min): en la misma cazuela, subir a fuego 6 de 9, añadir el pollo y remover 3-4 minutos. Está listo cuando está blanco por fuera en todas sus caras.","SABOR (1 min): añadir a la cazuela 1/2 cucharada de tomate frito, el tomillo, el romero y el azafrán (o el pimentón). Remover 1 minuto, sin dejar que el pimentón se queme (amarga).","CALDO (8 min): verter en la cazuela el caldo caliente del cazo, subir a fuego máximo (9) hasta que hierva (2-3 min) y bajar a 5 de 9 durante 5 minutos para que coja sabor.","ARROZ (15 min): añadir a la cazuela los 100 g de arroz SIN lavar (su almidón lo hace meloso), la sal, los guisantes y el brócoli. Remover una vez y dejar a fuego medio-bajo (4-5 de 9), hirviendo suave, 15 minutos sin tapa, removiendo con cuidado cada 5 min. Está listo cuando el grano está tierno con un puntito firme en el centro y queda caldo meloso alrededor. TEMPERATURA DEL POLLO: en la cazuela, pinchar el termómetro de cocina en el centro del dado de pollo más grueso, sin tocar el fondo ni las paredes de la cazuela, y esperar unos segundos a que la cifra se estabilice: tiene que marcar 74 °C. Si no llega, seguir 2 minutos más y volver a medir. Si se queda seco antes de tiempo, añadir 50 ml de caldo o agua caliente.","REPOSO Y SERVIR (5 min): apagar el fuego, tapar la cazuela con su tapa y dejar reposar 5 minutos exactos, no más (sigue absorbiendo caldo y se pasa). Servir enseguida en los platos; un chorrito de limón por encima queda muy bien."],"foto":"https://upload.wikimedia.org/wikipedia/commons/thumb/f/f0/Arroz_caldoso%2C_Espa%C3%B1a.jpg/330px-Arroz_caldoso%2C_Espa%C3%B1a.jpg"}'::jsonb, 9, true),
  ('chef', 'recipe', 'lentejas-estofadas-con-verduras', '{"n":"Lentejas estofadas con verduras","pr":"Lenteja","sana":"Sí","dif":"Fácil","t":55,"val":"","com":"Variante: añade un puñado de espinacas los últimos 2 minutos o una pizca de comino con el pimentón. Al día siguiente están todavía más ricas.","cc":"Comida","rac":4,"cong":"Sí","nev":"3","tm":"Sí","ut":"Colador · tabla y cuchillo · pelador · olla grande de 4 L con tapa · cuchara de madera · taza medidora · cucharas sopera y de postre (para medir) · 2 platos hondos · 2 tarteras herméticas aptas para congelador · termómetro de cocina · temporizador. Versión TM5: Thermomix TM5 con vaso, tapa, cubilete, cestillo (como tapa antisalpicaduras) y espátula.","ing":[["300 g","Lentejas pardinas (no necesitan remojo)"],["1 mediana (unos 150 g)","Cebolla"],["1 (unos 150 g)","Pimiento verde o rojo"],["2 (unos 160 g)","Zanahoria"],["2 pequeñas (unos 300 g)","Patata"],["2 dientes","Ajo"],["1 hoja","Laurel"],["1 cdita (3 g)","Pimentón dulce (o de la Vera)"],["2 cdas (20 g)","Tomate frito"],["3 cdas (30 g)","Aceite de oliva virgen extra"],["1,3 litros al fuego / 1000 g en TM5","Agua"],["1 pastilla (10 g)","Caldo de verduras en pastilla (o 2 cditas de sal)"],["Al gusto","Sal y un chorrito de vinagre al servir (opcional)"]],"pasos":["LAVAR Y CORTAR (10 min): en el colador, lavar los 300 g de lentejas bajo el grifo 30 segundos y quitar alguna piedrecita. En la tabla con el cuchillo: cebolla y pimiento en dados de medio cm; ajo picado fino; zanahoria (pelada con el pelador) en rodajas de 1 cm; patata pelada en trozos de 2-3 cm «chascados» (cortar a medias y romper tirando: suelta almidón y espesa el caldo).","SOFRITO (10 min): en la olla grande de 4 L, 3 cucharadas de aceite a fuego medio (5 de 9) y esperar 1 min. Añadir cebolla, pimiento y ajo y remover con la cuchara de madera cada 2 min durante 8-10 min. Está listo cuando la cebolla está transparente y blanda, sin dorarse (si se dora, bajar a 4).","PIMENTÓN Y TOMATE (1 min): en la misma olla, bajar a fuego 3 de 9, añadir la cucharadita de pimentón y remover solo 20 segundos (se quema enseguida y amarga); añadir al momento las 2 cucharadas de tomate frito y remover 30 segundos.","TODO A LA OLLA (5 min): añadir a la olla las lentejas, la zanahoria, la patata, el laurel, la pastilla de caldo y 1,3 L de agua fría (medida con la taza medidora). Subir a fuego máximo (9 de 9) hasta que hierva (unos 5 min).","COCER (35-40 min): bajar a fuego suave (3-4 de 9), tapar la olla dejando una rendija y cocer 35-40 min, removiendo desde el fondo cada 10 min. Si se queda sin caldo, añadir 100 ml de agua caliente. Están listas cuando la lenteja está tierna (se aplasta con la lengua contra el paladar) y la patata se deshace al pincharla con un tenedor.","ESPESAR Y PROBAR (5 min): apagar el fuego y sacar el laurel. Aplastar 3-4 trozos de patata contra la pared de la olla con la cuchara de madera y remover: el caldo espesa. Probar y ajustar de sal. Dejar reposar 5 min con la olla tapada.","SERVIR Y GUARDAR: servir 2 platos hondos (unos 400 g cada uno), con un chorrito de vinagre si se quiere. Las otras 2 raciones, a las 2 tarteras; dejarlas templar destapadas (como mucho 1 h fuera de la nevera), taparlas y a la nevera o al congelador (ver Notas)."],"foto":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/21/Lentejas_estilo_de_la_abuela.jpg/330px-Lentejas_estilo_de_la_abuela.jpg"}'::jsonb, 10, true),
  ('chef', 'recipe', 'pollo-al-curry-suave-con-arroz-basmati', '{"n":"Pollo al curry suave con arroz basmati","pr":"Pollo","sana":"Sí","dif":"Fácil","t":45,"val":"","com":"Variante: cambia la mitad del pollo por garbanzos cocidos o añade un puñado de espinacas al final. Un poco de cebolleta picada por encima le da frescor.","cc":"Comida","rac":4,"cong":"Sí","nev":"2","tm":"No","ut":"Tabla y cuchillo · colador · olla grande de 4 L con tapa (arroz) · sartén honda o cazuela de 28 cm con tapa (curry) · cuchara de madera · plato (reservar el pollo) · taza medidora · abrelatas · exprimidor · 2 platos · 2 tarteras herméticas aptas para congelador · termómetro de cocina · temporizador.","ing":[["600 g","Contramuslos de pollo sin piel ni hueso (o pechuga)"],["1 grande (unos 200 g)","Cebolla"],["1 (unos 150 g)","Pimiento rojo"],["2 dientes","Ajo"],["2 cditas rasas (6 g)","Curry en polvo suave"],["1 lata (400 ml)","Leche de coco ligera (o nata ligera para cocinar)"],["200 g (4 cdas colmadas)","Tomate triturado"],["200 g","Guisantes congelados"],["320 g","Arroz basmati"],["2,5 litros + 2 cditas (10 g) de sal","Agua para cocer el arroz"],["2 cdas (20 g)","Aceite de oliva virgen extra"],["1/2","Limón (zumo, al final)"],["Al gusto","Sal"]],"pasos":["CORTAR (8 min): en la tabla con el cuchillo, el pollo en dados de 3 cm con una pizca de sal. La cebolla en dados de medio cm, el pimiento en trozos de 2-3 cm y el ajo picado fino.","AGUA DEL ARROZ: en la olla grande de 4 L, 2,5 L de agua con 2 cucharaditas de sal; tapar y poner a fuego máximo (9 de 9) hasta que hierva (10-12 min). Mientras, seguir con el curry.","DORAR EL POLLO (6 min): en la sartén honda de 28 cm, 1 cucharada de aceite a fuego medio-alto (7 de 9) y esperar 1 min. Poner el pollo en una sola capa, sin amontonar: 3 min sin moverlo y 3 min más removiendo. Está listo cuando está dorado por fuera (por dentro termina en la salsa). Sacarlo al plato.","SOFRITO (8 min): en la misma sartén, otra cucharada de aceite a fuego medio (5 de 9). Añadir cebolla, pimiento y ajo y cocinar 8 min removiendo cada 2 min con la cuchara de madera. Está listo cuando la cebolla está blanda y transparente.","ESPECIAS (30 s): en la sartén, bajar a 4 de 9, añadir las 2 cucharaditas de curry y remover 30 segundos, hasta que huela (no más: se quema y amarga).","SALSA (15 min): añadir a la sartén el tomate triturado, la leche de coco (agitar antes la lata) y el pollo con su jugo. Subir a 9 hasta que hierva, bajar a 3-4 de 9, tapar y cocer 12 min removiendo cada 4. Añadir los guisantes congelados y 3 min más. Está listo cuando el pollo, al partir el trozo más gordo, está blanco por dentro y la salsa cubre la cuchara. TEMPERATURA: en la sartén honda, pinchar el termómetro de cocina en el centro del dado de pollo más gordo, sin tocar la sartén, y esperar unos segundos a que la cifra se estabilice: tiene que marcar 74 °C. Si no llega, seguir 2 minutos más tapado a fuego 3-4 de 9 y volver a medir. Si espesa demasiado, añadir 50 ml de agua.","ARROZ (12 min): lavar los 320 g de arroz en el colador bajo el grifo 45 segundos. Echarlo en la olla grande con el agua hirviendo, remover una vez, quitar la tapa y cocer a fuego 6 de 9 durante 11-12 min. Está listo cuando el grano está tierno pero entero. Escurrir en el colador.","TERMINAR Y SERVIR: apagar la sartén, añadir el zumo de medio limón (con el exprimidor) y probar de sal. Servir 2 platos con arroz y curry al lado. Las otras 2 raciones, a las 2 tarteras (arroz y curry juntos); templar destapadas como mucho 1 h, tapar y a la nevera o al congelador (ver Notas)."],"foto":"https://upload.wikimedia.org/wikipedia/commons/thumb/b/b3/Chicken_Curry_with_Rice.jpg/330px-Chicken_Curry_with_Rice.jpg"}'::jsonb, 11, true),
  ('chef', 'recipe', 'albondigas-de-pollo-en-salsa-de-tomate-casera', '{"n":"Albóndigas de pollo en salsa de tomate casera","pr":"Pollo","sana":"Sí","dif":"Media","t":60,"val":"","com":"Variante: mete un dadito de mozzarella dentro de cada albóndiga al formarla y quedan rellenas de queso fundido. Con pasta integral o arroz basmati se convierten en plato único.","cc":"Comida","rac":4,"cong":"Sí","nev":"3","tm":"No","ut":"Tabla y cuchillo · pelador · rallador (lado grueso) · bol grande (masa) · tenedor · plato llano con la harina · bandeja o plato grande (albóndigas crudas) · plato limpio (albóndigas doradas) · sartén grande de 28 cm (dorar) · cazuela de 24-28 cm con tapa (salsa) · espumadera · cuchara de madera · taza medidora · batidora de brazo (opcional) · tarro pequeño con tapa (tomate para la pizza) · 2 platos · 2 tarteras herméticas aptas para congelador · termómetro de cocina · temporizador.","ing":[["600 g","Carne picada de pollo (o pechuga picada en la carnicería)"],["1","Huevo"],["40 g (4 cdas)","Pan rallado"],["3 dientes (2 para la carne y 1 para la salsa)","Ajo"],["1 cda","Perejil picado (fresco o seco)"],["2 cdas (20 g)","Harina de trigo (para enharinar)"],["1 mediana (150 g)","Cebolla"],["1 (unos 80 g)","Zanahoria (endulza la salsa)"],["800 g (1 bote grande)","Tomate triturado"],["4 cdas (40 g)","Aceite de oliva virgen extra"],["1 cdita (4 g)","Azúcar (corrige la acidez del tomate)"],["150 ml","Agua"],["Al gusto","Sal y pimienta"]],"pasos":["PICAR (5 min): en la tabla, picar muy fino los 3 dientes de ajo (2 para la carne y 1 para la salsa). Cebolla en dados de medio centímetro. Pelar la zanahoria con el pelador y rallarla con el lado grueso del rallador.","MASA (5 min): en el bol grande, poner los 600 g de pollo picado, el huevo, 4 cucharadas de pan rallado, los 2 dientes de ajo, el perejil, 1/2 cucharadita de sal y pimienta. Mezclar con el tenedor y luego con las manos 1 min. Está lista cuando no se pega a las manos mojadas; si está muy blanda, 1 cucharada más de pan rallado.","FORMAR (10 min): con las manos mojadas, hacer bolas del tamaño de una nuez (unos 25 g; salen unas 24). Pasarlas por el plato con harina, sacudir el exceso y dejarlas en la bandeja.","DORAR (8 min): en la sartén grande de 28 cm, 3 cucharadas de aceite a fuego medio-alto (7 de 9) y esperar 1 min. Dorar las albóndigas en 2 tandas, 3-4 min por tanda, girándolas con la cuchara. Están listas cuando están doradas por fuera (por dentro siguen crudas: terminan en la salsa). Sacarlas con la espumadera al plato limpio.","SOFRITO DE LA SALSA (5 min): en la cazuela, 1 cucharada de aceite a fuego medio (5 de 9): cebolla, zanahoria rallada y el diente de ajo restante, 5 min removiendo con la cuchara de madera. Está listo cuando la cebolla está transparente.","TOMATE (15 min): añadir a la cazuela los 800 g de tomate triturado, 150 ml de agua (taza medidora), 1 cucharadita de azúcar y 1/2 de sal. Subir a fuego 9 hasta que borbotee, bajar a 3 de 9 y cocer 15 min con la tapa entreabierta (salpica), removiendo cada 5 min. Opcional: triturar 30 segundos con la batidora de brazo para que quede fina.","RESERVAR TOMATE PARA LA PIZZA (1 min): sacar 6 cucharadas (unos 120 g) de salsa al tarro pequeño, dejar templar y a la nevera (3 días) para la pizza de pollo.","COCER LAS ALBÓNDIGAS (15 min): meter las albóndigas en la cazuela con la salsa, tapar y cocer a fuego suave (3 de 9) 15 min, moviendo la cazuela con suavidad a los 7 min (con cuchara se rompen). Están listas cuando, al partir la más gorda, está blanca por dentro sin nada rosado y la salsa ha espesado. TEMPERATURA: en la cazuela, pinchar el termómetro de cocina en el centro de la albóndiga más gorda, sin tocar el fondo de la cazuela, y esperar unos segundos a que la cifra se estabilice: tiene que marcar 74 °C. Si no llega, seguir 2 minutos más tapada a fuego 3 de 9 y volver a medir.","SERVIR Y GUARDAR: 6 albóndigas con salsa por plato (2 platos). Las otras 12, con su salsa, a las 2 tarteras; templar destapadas como mucho 1 h, tapar y a la nevera o al congelador (ver Notas)."],"foto":"https://upload.wikimedia.org/wikipedia/commons/thumb/7/74/Cazuela_de_Alb%C3%B3ndigas_de_carne_con_sofrito_de_tomate%2C_cebolla%2C_ajo_y_perejil.jpg/330px-Cazuela_de_Alb%C3%B3ndigas_de_carne_con_sofrito_de_tomate%2C_cebolla%2C_ajo_y_perejil.jpg"}'::jsonb, 12, true),
  ('chef', 'recipe', 'merluza-en-papillote-con-calabacin-zanahoria-y-limon', '{"n":"Merluza en papillote con calabacín, zanahoria y limón","pr":"Merluza","sana":"Sí","dif":"Fácil","t":35,"val":"","com":"Variante: añade a la cama de verdura unos tomates cherry partidos o un puñado de guisantes. Abrir el paquete en la mesa tiene gracia: sale todo el aroma del limón.","cc":"Cena","rac":2,"cong":"No (la merluza cocinada se reseca y la verdura suelta agua)","nev":"1","tm":"No","ut":"Plato hondo (descongelar) · papel de cocina · tabla y cuchillo · pelador · bol mediano (verduras) · papel de horno (2 hojas de unos 40 x 30 cm) · bandeja del horno · horno · manopla de horno · tijeras · exprimidor · tenedor · 2 platos · termómetro de cocina · temporizador.","ing":[["2 lomos (unos 300 g)","Merluza congelada en lomos sin piel (o fresca)"],["1 pequeño (unos 200 g)","Calabacín"],["1 (unos 80 g)","Zanahoria"],["1/2 (unos 75 g)","Cebolla"],["1","Limón (4 rodajas finas + zumo de medio)"],["1 diente","Ajo"],["2 cdas (20 g)","Aceite de oliva virgen extra"],["2 cdas (30 ml)","Agua"],["1 pizca","Orégano o tomillo seco"],["Al gusto","Sal y pimienta negra"]],"pasos":["DESCONGELAR (la víspera): pasar los 2 lomos del congelador al plato hondo, tapados, y a la nevera unas 12 h. Antes de cocinar, secarlos bien con papel de cocina.","PRECALENTAR (10 min): sacar la bandeja del horno. Encender el horno a 200 °C, calor arriba y abajo, 10 minutos.","VERDURA (8 min): en la tabla, el calabacín con piel en bastones de medio cm de grosor y 6 cm de largo; la zanahoria pelada con el pelador en bastones más finos (2-3 mm, porque tarda más en hacerse); la cebolla en juliana fina y el ajo en láminas. En el bol mediano, mezclarlo todo con 1 cucharada de aceite, sal y pimienta.","MONTAR (5 min): poner las 2 hojas de papel de horno sobre la encimera. En el centro de cada una, la mitad de la verdura como cama; encima un lomo salpimentado, 2 rodajas de limón, el orégano, media cucharada de aceite y 1 cucharada de agua.","CERRAR (2 min): juntar los dos lados largos del papel por encima del pescado y doblarlos juntos 3-4 veces hacia abajo; retorcer los extremos como un caramelo. Tiene que quedar bien cerrado pero con aire dentro (el papel no debe tocar el pescado).","HORNEAR (15-18 min): poner los 2 paquetes en la bandeja del horno y meterla a altura media (segunda guía desde abajo). 15 min si los lomos tienen unos 2 cm de grosor; 18 min si son más gruesos. El paquete se hincha.","COMPROBAR: sacar la bandeja con la manopla y abrir un paquete con las tijeras, apartando la cara (sale vapor muy caliente). Está lista cuando la merluza está blanca y opaca y se separa en láminas al tocarla con un tenedor; si aún está translúcida, cerrar y 3 min más. TEMPERATURA: con el paquete abierto sobre la bandeja, pinchar el termómetro de cocina en la parte más gruesa del lomo, sin tocar la bandeja ni el papel, y esperar unos segundos a que la cifra se estabilice: tiene que marcar 63 °C. Si no llega, cerrar el paquete, hornear 2 minutos más y volver a medir.","SERVIR: poner cada paquete en un plato, abrirlo en la mesa y exprimir por encima el zumo de medio limón (con el exprimidor)."],"foto":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/63/Branzino_al_cartoccio.jpg/330px-Branzino_al_cartoccio.jpg"}'::jsonb, 13, true),
  ('chef', 'recipe', 'tortilla-de-calabacin-y-cebolla', '{"n":"Tortilla de calabacín y cebolla","pr":"Huevo","sana":"Sí","dif":"Media","t":30,"val":"","com":"Variante: añade a la mezcla 50 g de queso rallado o unos taquitos de jamón cocido. Fría, en bocadillo, está buenísima al día siguiente.","cc":"Cena","rac":2,"cong":"No (el huevo cuajado se vuelve gomoso y suelta agua)","nev":"2","tm":"No","ut":"Tabla y cuchillo · sartén antiadherente de 22-24 cm con tapa · cuchara de madera · colador · bol grande · tenedor · papel de cocina · espátula de silicona · plato llano más grande que la sartén (para darle la vuelta) · paño de cocina · temporizador.","ing":[["1 grande (unos 400 g)","Calabacín"],["1 mediana (150 g)","Cebolla"],["5","Huevos"],["4 cdas (40 g)","Aceite de oliva virgen extra"],["Al gusto","Sal"],["Opcional","Pimienta y una pizca de comino"]],"pasos":["CORTAR (5 min): en la tabla, el calabacín con piel en cuartos a lo largo y luego en láminas de medio centímetro. La cebolla en juliana fina (tiras de medio cm).","POCHAR (15 min): en la sartén de 22-24 cm, 3 cucharadas de aceite a fuego medio (5 de 9) y esperar 1 min. Añadir la cebolla y cocinar 5 min removiendo con la cuchara de madera. Añadir el calabacín y 1/2 cucharadita de sal, tapar y cocinar 10 min removiendo cada 3. Está listo cuando el calabacín está blando y apenas dorado.","ESCURRIR (2 min): pasar la verdura al colador, puesto sobre el bol grande, y dejarla escurrir 2 min (el agua hace que la tortilla se rompa). Tirar el líquido del bol y secarlo con papel de cocina.","BATIR (2 min): en el bol grande, batir los 5 huevos con una pizca de sal con el tenedor 30 segundos. Añadir la verdura escurrida, mezclar y dejar reposar 2 min.","PRIMERA CARA (4 min): limpiar la sartén con papel de cocina, poner 1 cucharada de aceite a fuego medio-alto (6 de 9) y esperar 1 min. Verter la mezcla, moverla 20 segundos con la espátula y despegar los bordes; bajar a 4 de 9 y dejar 3-4 min. Está lista para girar cuando el borde está cuajado y al mover la sartén el centro apenas tiembla.","DAR LA VUELTA (1 min): apagar el fuego. Poner el plato grande boca abajo sobre la sartén, sujetarlo con la mano encima (protegida con el paño) y girar todo de golpe sobre el fregadero. Deslizar la tortilla otra vez a la sartén con la parte cruda hacia abajo.","TERMINAR (2-3 min): en la sartén a fuego 4 de 9, 2 min (jugosa) o 3 min (más hecha). Está lista cuando al pinchar el centro con un cuchillo sale casi limpio. Pasarla al plato y dejarla reposar 2 min antes de cortarla en 4."],"foto":"https://upload.wikimedia.org/wikipedia/commons/thumb/1/12/Tortilla_de_calabac%C3%ADn.jpg/330px-Tortilla_de_calabac%C3%ADn.jpg"}'::jsonb, 14, true),
  ('chef', 'recipe', 'garbanzos-salteados-con-espinacas-pimenton-y-huevo', '{"n":"Garbanzos salteados con espinacas, pimentón y huevo","pr":"Garbanzo","sana":"Sí","dif":"Fácil","t":20,"val":"","com":"Variante: cambia el huevo cocido por un huevo a la plancha o añade unos taquitos de jamón al sofrito. Un pellizco de comino le da un aire andaluz.","cc":"Comida","rac":2,"cong":"No (las espinacas se aguan)","nev":"2","tm":"No","ut":"Colador · tabla y cuchillo · abrelatas (si hace falta) · cazo pequeño de 1-1,5 L (huevos) · bol con agua fría · cuchara · sartén grande de 28 cm con tapa · cuchara de madera · 2 platos · temporizador.","ing":[["1 bote (400 g; unos 240 g escurridos)","Garbanzos cocidos"],["200 g (media bolsa)","Espinacas frescas (o 4 bolas de espinacas congeladas)"],["2","Huevos"],["2 dientes","Ajo"],["1/2 (unos 75 g)","Cebolla"],["1 cdita (3 g)","Pimentón de la Vera (o dulce)"],["1/2 cdita","Comino molido (opcional)"],["3 cdas (30 g)","Aceite de oliva virgen extra"],["1 chorrito","Vinagre o zumo de limón"],["2 rebanadas (opcional)","Pan, para mojar"],["Al gusto","Sal"]],"pasos":["HUEVOS (10 min, a la vez que lo demás): en el cazo pequeño, agua que cubra los huevos 2 cm, a fuego máximo (9 de 9) hasta que hierva. Meter los 2 huevos con la cuchara, bajar a 6 de 9 y contar 7 min (yema melosa) o 9 min (yema cuajada). Pasarlos al bol con agua fría 3 min, pelarlos y partirlos en cuartos en la tabla.","PREPARAR (4 min): escurrir y enjuagar los garbanzos en el colador y dejarlos escurrir bien (secos se tuestan mejor). En la tabla, el ajo en láminas finas y la cebolla en juliana fina. Si las espinacas son frescas, lavarlas en el colador.","SOFRITO (5 min): en la sartén grande, 2 cucharadas de aceite a fuego medio (5 de 9) y esperar 1 min. Cebolla 4 min removiendo con la cuchara de madera; añadir el ajo y 1 min más. Está listo cuando la cebolla está blanda y el ajo empieza a dorarse por los bordes.","GARBANZOS (5 min): en la misma sartén, subir a fuego 7 de 9, añadir los garbanzos y 1 cucharada de aceite y saltear 4-5 min removiendo cada minuto. Están listos cuando algunos están dorados y crujientes por fuera.","PIMENTÓN (30 s): bajar a fuego 3 de 9, añadir el pimentón y el comino y remover 20-30 segundos (el pimentón se quema enseguida y amarga).","ESPINACAS (3 min): añadir a la sartén las espinacas por puñados, tapar 1 min y remover 2 min más. Están listas cuando han reducido y están verde intenso. Salar y añadir un chorrito de vinagre o limón.","SERVIR: repartir en 2 platos y poner encima los cuartos de huevo con una pizca de sal y pimentón. Pan para mojar, si se quiere."],"foto":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/eb/GarbanzosConEspinacas.jpg/330px-GarbanzosConEspinacas.jpg"}'::jsonb, 15, true),
  ('chef', 'recipe', 'crema-de-calabaza-y-zanahoria', '{"n":"Crema de calabaza y zanahoria","pr":"Calabaza","sana":"Sí","dif":"Fácil","t":45,"val":"","com":"Variante: un poco de jengibre rallado o una pizca de curry suave al rehogar la cebolla le da un toque exótico. Las pipas de calabaza por encima aportan el crujiente.","cc":"Cena","rac":4,"cong":"Sí","nev":"3","tm":"Sí","ut":"Tabla y cuchillo grande · pelador · cuchara (quitar pepitas) · olla grande de 4-5 L con tapa · cuchara de madera · taza medidora · batidora de brazo · cucharón · cuencos · 2 tarteras herméticas aptas para congelador · termómetro de cocina · temporizador. Versión TM5: Thermomix TM5 con vaso, tapa, cubilete y espátula (y un paño para sujetar el cubilete al triturar).","ing":[["800 g (pelada y sin pepitas)","Calabaza (tipo cacahuete o butternut)"],["3 (unos 250 g)","Zanahoria"],["1 mediana (150 g)","Cebolla"],["1 pequeña (150 g)","Patata"],["700 ml al fuego / 650 g en TM5","Agua"],["1 pastilla (10 g)","Caldo de verduras en pastilla (o 1 cdita y media de sal)"],["2 cdas (20 g)","Aceite de oliva virgen extra"],["2 (opcional)","Quesitos en porción (más cremosa)"],["1 pizca","Nuez moscada o comino (opcional)"],["Al gusto","Sal y pimienta"],["Para servir (opcional)","Pipas de calabaza o picatostes y un hilo de aceite"]],"pasos":["PELAR Y CORTAR (12 min): en la tabla, con el cuchillo grande, cortar la calabaza en rodajas de 3 cm, quitarles la piel con el cuchillo o el pelador y las pepitas con la cuchara; trocearla en dados de 3 cm. Zanahoria pelada en rodajas de 1 cm. Cebolla en trozos de 2 cm. Patata pelada en dados de 2 cm.","REHOGAR (6 min): en la olla grande, 2 cucharadas de aceite a fuego medio (5 de 9) y esperar 1 min. Añadir la cebolla y remover cada minuto con la cuchara de madera durante 5 min. Está lista cuando está transparente, sin dorarse.","COCER (25 min): añadir a la olla la calabaza, la zanahoria, la patata, la pastilla y 700 ml de agua (taza medidora; no tiene que cubrirlo todo, la calabaza suelta agua). Fuego máximo (9) hasta que hierva (unos 5 min), bajar a 4 de 9, tapar y cocer 20 min. Está lista cuando la zanahoria se aplasta fácil con un tenedor.","TRITURAR (8 min): apagar y dejar templar 5 min con la olla destapada. Añadir los quesitos y la nuez moscada y triturar con la batidora de brazo unos 3 min, moviéndola por toda la olla. Está lista cuando es una crema lisa sin grumos. Si queda muy espesa, añadir 100 ml de agua y batir otra vez; probar de sal.","SERVIR Y GUARDAR: con el cucharón, 2 cuencos (unos 350 ml cada uno) con un hilo de aceite y pipas o picatostes. Las otras 2 raciones, a las 2 tarteras; templar destapadas como mucho 1 h, tapar y a la nevera o al congelador (ver Notas)."],"foto":"https://upload.wikimedia.org/wikipedia/commons/thumb/b/b2/Receta_de_crema_de_calabaza_y_zanahoria_-_Vegan_Pumpkin_soup_%284995482360%29.jpg/330px-Receta_de_crema_de_calabaza_y_zanahoria_-_Vegan_Pumpkin_soup_%284995482360%29.jpg"}'::jsonb, 16, true),
  ('chef', 'recipe', 'pasta-integral-con-brocoli-atun-y-limon', '{"n":"Pasta integral con brócoli, atún y limón","pr":"Pasta integral","sana":"Sí","dif":"Fácil","t":25,"val":"","com":"Variante: añade unos tomates cherry partidos o unas alcaparras al final. Fría y con un chorrito más de limón funciona como ensalada de pasta para llevar.","cc":"Comida","rac":2,"cong":"No (la pasta se ablanda)","nev":"2","tm":"No","ut":"Olla grande de 4 L con tapa · tabla y cuchillo · rallador (lado fino) · exprimidor · abrelatas (si hace falta) · taza (reservar agua de cocción) · colador · sartén grande de 28 cm · cuchara de madera · 2 platos · temporizador.","ing":[["180 g","Pasta integral corta (macarrones o espirales)"],["250 g (1 cabeza pequeña)","Brócoli"],["2 latas (unos 160 g escurrido)","Atún al natural o en aceite de oliva"],["2 dientes","Ajo"],["1","Limón (ralladura y zumo)"],["3 cdas (30 g)","Aceite de oliva virgen extra"],["2 litros + 2 cditas (10 g) de sal","Agua para la pasta"],["1 pizca (opcional)","Guindilla o pimienta"],["2 cdas (20 g, opcional)","Queso rallado"]],"pasos":["AGUA (10 min): en la olla grande, 2 L de agua y 2 cucharaditas de sal; tapar y poner a fuego máximo (9 de 9) hasta que hierva con burbujas grandes.","PREPARAR (5 min): en la tabla, el brócoli en ramilletes pequeños de 3 cm (el tronco, pelado y en dados de 1 cm). El ajo en láminas finas. Rallar la piel del limón con el lado fino del rallador (solo lo amarillo) y exprimir medio limón con el exprimidor. Escurrir el atún.","PASTA (unos 11 min): echar la pasta en la olla con el agua hirviendo, remover y cocer sin tapa a fuego 7 de 9 el tiempo que diga el envase menos 1 minuto. Remover a los 2 min para que no se pegue.","BRÓCOLI EN LA MISMA OLLA (4 min): cuando a la pasta le queden 4 min, echar el brócoli en la olla. Antes de escurrir, sacar con la taza unos 100 ml del agua de cocción. Escurrir pasta y brócoli juntos en el colador. La pasta está lista cuando está tierna con un punto firme en el centro.","AJO (2 min, mientras se cuece la pasta): en la sartén grande, 3 cucharadas de aceite y el ajo a fuego medio-bajo (4 de 9) durante 2 min. Está listo cuando el ajo está apenas dorado (si se tuesta, amarga). Añadir la guindilla.","SALTEAR (2 min): subir la sartén a 6 de 9 y añadir la pasta con el brócoli, el atún, la ralladura de limón y 3-4 cucharadas del agua de cocción. Remover 1-2 min. Está lista cuando la pasta está brillante y suelta, sin quedar seca.","SERVIR: apagar, añadir el zumo de limón, probar de sal y repartir en 2 platos con el queso rallado por encima."],"foto":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/e5/BroccoliPasta.jpg/330px-BroccoliPasta.jpg"}'::jsonb, 17, true),
  ('chef', 'recipe', 'fajitas-de-pollo-y-pimiento-con-yogur', '{"n":"Fajitas de pollo y pimiento con yogur","pr":"Pollo","sana":"Sí","dif":"Fácil","t":30,"val":"","com":"Variante: añade al relleno unos granos de maíz o unas alubias rojas de bote. Una pizca de guindilla en la salsa de yogur le da un punto picante.","cc":"Cena","rac":2,"cong":"No (el pimiento se ablanda y el yogur se corta)","nev":"2","tm":"No","ut":"Tabla y cuchillo · bol mediano (marinar) · bol pequeño y tenedor (salsa) · exprimidor · sartén grande de 28 cm · espátula o pinzas · plato (reservar) · papel de cocina · paño limpio (tortillas) · 2 platos · termómetro de cocina · temporizador.","ing":[["300 g","Pechuga o contramuslo de pollo"],["1","Pimiento rojo"],["1","Pimiento verde"],["1 mediana (150 g)","Cebolla"],["4","Tortillas de trigo (integrales si hay)"],["1 (125 g)","Yogur natural (o griego) sin azúcar"],["1 cdita (3 g)","Pimentón dulce"],["1/2 cdita","Comino molido"],["1/2 cdita (o 1 diente picado)","Ajo en polvo"],["1/2","Limón (zumo)"],["2 cdas (20 g)","Aceite de oliva virgen extra"],["Al gusto","Sal y pimienta"],["Opcional","Hojas de lechuga y queso rallado"]],"pasos":["CORTAR (8 min): en la tabla, el pollo en tiras de 1 cm de grosor y unos 6 cm de largo; los pimientos, sin semillas, en tiras de 1 cm; la cebolla en juliana de medio cm.","MARINAR (5 min): en el bol mediano, mezclar el pollo con el pimentón, el comino, el ajo en polvo, el zumo de medio limón (con el exprimidor), 1 cucharada de aceite y 1/2 cucharadita de sal. Dejar 5 min.","SALSA (2 min): en el bol pequeño, el yogur con una pizca de sal, un chorrito de limón y pimienta; remover con el tenedor y guardar en la nevera.","VERDURA (6 min): en la sartén grande, 1 cucharada de aceite a fuego fuerte (8 de 9) y esperar 1 min. Pimientos y cebolla 5-6 min, removiendo cada minuto con la espátula. Están listos cuando están tiernos pero con un punto crujiente y algo tostados. Sacarlos al plato.","POLLO (5 min): en la misma sartén a fuego fuerte (8 de 9), el pollo extendido en una capa: 2 min sin moverlo y 2-3 min más removiendo. Está listo cuando está dorado y, al partir la tira más gruesa, blanco por dentro. TEMPERATURA: en la sartén grande, pinchar el termómetro de cocina en el centro de la tira de pollo más gruesa, sin tocar la sartén, y esperar unos segundos a que la cifra se estabilice: tiene que marcar 74 °C. Si no llega, seguir 2 minutos más y volver a medir. Volver a echar la verdura y saltear 1 min. Pasar todo al plato y taparlo.","TORTILLAS (2 min): limpiar la sartén con papel de cocina y ponerla a fuego medio (5 de 9). Calentar cada tortilla 20 segundos por lado y guardarlas envueltas en el paño para que no se sequen.","MONTAR: en cada tortilla, 1 cucharada de salsa de yogur, lechuga, una cuarta parte del relleno y un poco de queso; enrollar. 2 por persona."],"foto":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/cf/Chicken_fajitas.jpg/330px-Chicken_fajitas.jpg"}'::jsonb, 18, true),
  ('chef', 'recipe', 'revuelto-de-champinones-espinacas-y-ajo-con-tostada', '{"n":"Revuelto de champiñones, espinacas y ajo con tostada","pr":"Huevo","sana":"Sí","dif":"Fácil","t":15,"val":"","com":"Variante: añade unos taquitos de jamón con los champiñones o frota la tostada caliente con medio diente de ajo. Un hilo de aceite sobre el pan le da el toque final.","cc":"Cena","rac":2,"cong":"No","nev":"0 (al momento; champiñones y espinacas salteados sin huevo: 2 días)","tm":"No","ut":"Tabla y cuchillo · cuchillo de sierra (pan) · papel de cocina húmedo (limpiar champiñones) · colador (espinacas) · bol y tenedor (huevos) · tostadora (o la misma sartén) · sartén antiadherente de 24-28 cm · espátula de silicona · 2 platos · temporizador.","ing":[["250 g (1 bandeja)","Champiñón laminado (champiñones)"],["100 g (2 puñados grandes)","Espinacas frescas"],["4","Huevos"],["2 dientes","Ajo"],["2 rebanadas grandes de 1,5 cm","Pan de barra o rústico"],["2 cdas (20 g)","Aceite de oliva virgen extra"],["1 cda (15 ml, opcional)","Leche (más cremoso)"],["Al gusto","Sal y pimienta"],["1 pizca (opcional)","Perejil"]],"pasos":["PREPARAR (4 min): en la tabla, el ajo en láminas finas. Si los champiñones no vienen laminados, limpiarlos con papel de cocina húmedo (sin mojarlos) y cortarlos en láminas de medio cm. Lavar las espinacas en el colador y escurrir. En el bol, batir los 4 huevos con la leche, una pizca de sal y pimienta, 20 segundos con el tenedor.","TOSTAR EL PAN (3 min): en la tabla, cortar 2 rebanadas de 1,5 cm con el cuchillo de sierra. Tostadora 2-3 min, o en la sartén sin aceite a fuego 7 de 9, 1,5 min por lado. Están listas cuando están doradas y crujientes. Dejarlas en los platos.","AJO Y CHAMPIÑÓN (6 min): en la sartén, 2 cucharadas de aceite y el ajo a fuego medio (5 de 9) durante 1 min. Subir a fuego fuerte (8 de 9), añadir los champiñones y no tocarlos 2 min (así se doran en vez de cocerse); después remover 3 min con la espátula. Están listos cuando han soltado el agua, se ha evaporado y están dorados. Salar al final.","ESPINACAS (1 min): añadir las espinacas a la sartén y remover 1 min hasta que reduzcan.","REVOLVER (2 min): bajar a fuego suave (3 de 9). Verter el huevo batido en la sartén y remover sin parar con la espátula, de los bordes al centro, 1,5-2 min. Apagar cuando todavía está brillante y cremoso: se termina de hacer con el calor de la sartén.","SERVIR: repartir el revuelto encima o al lado de las tostadas, con pimienta y perejil. Comer al momento."],"foto":"https://upload.wikimedia.org/wikipedia/commons/thumb/b/bd/Raci%C3%B3n_de_tapa%2C_revuelto_de_ajos_tiernos_y_champi%C3%B1ones.jpg/330px-Raci%C3%B3n_de_tapa%2C_revuelto_de_ajos_tiernos_y_champi%C3%B1ones.jpg"}'::jsonb, 19, true),
  ('chef', 'recipe', 'pizza-de-calabacin-champinon-y-mozzarella', '{"n":"Pizza de calabacín, champiñón y mozzarella","pr":"Masa de pizza","sana":"Moderado","dif":"Fácil","t":35,"val":"","com":"Variante: al sacarla, añade un puñado de espinacas crudas o unas migas de atún. Un hilo de aceite con orégano en los bordes los deja más dorados.","cc":"Cena","rac":2,"cong":"No (horneada pierde lo crujiente)","nev":"2","tm":"No","ut":"Horno · bandeja del horno (con el papel de hornear que trae la masa) · tabla y cuchillo · papel de cocina · bol pequeño (salsa) · cuchara · tenedor · espátula ancha · manopla de horno · tabla grande o plato grande (cortar) · cortapizzas o cuchillo grande · temporizador.","ing":[["1 rollo (260 g)","Masa de pizza refrigerada en rollo (Alipende, Ahorramás)"],["6 cdas (120 g)","Tomate triturado (o la salsa de tomate casera de las albóndigas)"],["1 bola (125 g)","Mozzarella fresca (o 100 g de mozzarella rallada)"],["1/2 (unos 150 g)","Calabacín"],["100 g (media bandeja)","Champiñón laminado"],["1/4 (unos 40 g, opcional)","Cebolla"],["1 cdita","Orégano seco"],["1 cda (10 g)","Aceite de oliva virgen extra"],["1 pizca","Sal y pimienta"]],"pasos":["PRECALENTAR (10 min): sacar la masa de la nevera para que se atempere (así no se rompe al desenrollarla). Sacar la bandeja del horno y colocar la rejilla a altura media (segunda guía desde abajo). Encender el horno a 220 °C (o la temperatura que diga el envase de la masa), calor arriba y abajo, y dejar que se caliente 10 minutos.","VERDURA (6 min): en la tabla, el calabacín con piel en rodajas muy finas (2-3 mm) y la cebolla en juliana fina. Secar el calabacín con papel de cocina (si queda agua, la base no cruje). Si el champiñón no viene laminado, láminas de 3-4 mm.","SALSA (1 min): en el bol pequeño, el tomate con una pizca de sal, la mitad del orégano y unas gotas de aceite; remover con la cuchara.","EXTENDER LA MASA (2 min): desenrollar la masa sobre la bandeja del horno con su propio papel de hornear debajo. Pinchar la base con el tenedor 8-10 veces para que no haga globos.","MONTAR (4 min): con la cuchara, extender el tomate dejando 1,5 cm de borde sin salsa. Repartir el calabacín, el champiñón y la cebolla en una sola capa, sin amontonar. Escurrir la mozzarella con papel de cocina, partirla en trozos de 1-2 cm y repartirla. Resto del orégano, pimienta y un hilo de aceite.","HORNEAR (12-15 min): meter la bandeja en el horno a altura media (segunda guía desde abajo). A los 7 minutos, con la manopla, darle media vuelta a la bandeja (180°) si el horno dora más por un lado. En total, 12-15 min, o el tiempo que indique el envase de la masa si es distinto.","COMPROBAR: está hecha cuando los bordes están dorados, la base está crujiente al levantar una esquina con la espátula y el queso está fundido y con burbujas. Si la base sigue blanda, 2-3 min más bajando la bandeja a la guía más baja.","REPOSAR Y CORTAR: sacar la bandeja con la manopla (quema mucho) y dejar reposar la pizza 2 minutos. Deslizarla con su papel a la tabla grande y cortarla en 8 porciones con el cortapizzas o un cuchillo grande."],"foto":"https://upload.wikimedia.org/wikipedia/commons/thumb/1/17/Pizza_with_mushrooms_and_zucchini.jpg/330px-Pizza_with_mushrooms_and_zucchini.jpg"}'::jsonb, 20, true),
  ('chef', 'recipe', 'pizza-de-pollo-pimiento-y-cebolla-con-tomate-casero', '{"n":"Pizza de pollo, pimiento y cebolla con tomate casero","pr":"Masa de pizza","sana":"Moderado","dif":"Fácil","t":35,"val":"","com":"Variante: un hilo de miel con pimentón por encima al sacarla le da un punto barbacoa. Con el tomate casero de las albóndigas sabe a pizzería.","cc":"Cena","rac":2,"cong":"No (horneada pierde lo crujiente)","nev":"2","tm":"No","ut":"Horno · bandeja del horno (con el papel de hornear que trae la masa) · tabla y cuchillo · sartén de 24-28 cm (verdura y pollo) · espátula ancha · papel de cocina · cuchara · tenedor · manopla de horno · tabla grande o plato grande (cortar) · cortapizzas o cuchillo grande · termómetro de cocina · temporizador.","ing":[["1 rollo (260 g)","Masa de pizza refrigerada en rollo (Alipende, Ahorramás)"],["6 cdas (120 g)","Salsa de tomate casera (la reservada de las albóndigas) o tomate triturado"],["150 g","Pollo cocinado sobrante (de las fajitas o el curry) o 150 g de pechuga cruda en tiras"],["1/2","Pimiento rojo"],["1/2","Pimiento verde"],["1/2 (unos 75 g)","Cebolla"],["1 bola (125 g)","Mozzarella fresca (o 100 g de mozzarella rallada)"],["1 cdita","Orégano seco"],["1/2 cdita (opcional)","Pimentón dulce"],["1 cda (10 g)","Aceite de oliva virgen extra"],["1 pizca","Sal y pimienta"]],"pasos":["PRECALENTAR (10 min): sacar la masa de la nevera para que se atempere. Sacar la bandeja del horno y colocar la rejilla a altura media (segunda guía desde abajo). Encender el horno a 220 °C (o la temperatura que diga el envase de la masa), calor arriba y abajo, 10 minutos.","CORTAR (5 min): en la tabla, los pimientos sin semillas en tiras finas de medio cm y la cebolla en juliana fina. El pollo cocinado, desmigado o en tiras de 1 cm (si es crudo, en tiras finas de 1 cm).","SALTEAR (6-10 min): en la sartén, 1 cucharada de aceite a fuego medio-alto (7 de 9) y esperar 1 min. Pimientos y cebolla 5 min removiendo con la espátula; están listos cuando están blandos (crudos sueltan agua sobre la masa). Si el pollo es crudo, añadirlo y saltear 4 min más hasta que esté blanco por dentro; si es cocinado, solo 1 min con el pimentón para calentarlo. TEMPERATURA (en los dos casos): en la sartén, pinchar el termómetro de cocina en el centro de la tira de pollo más gruesa, sin tocar la sartén, y esperar unos segundos a que la cifra se estabilice: tiene que marcar 74 °C (pollo crudo cocinado ahora o pollo de sobras recalentado). Si no llega, seguir 2 minutos más removiendo y volver a medir.","EXTENDER LA MASA (2 min): desenrollar la masa sobre la bandeja del horno con su propio papel de hornear debajo. Pinchar la base con el tenedor 8-10 veces.","MONTAR (3 min): con la cuchara, extender la salsa de tomate dejando 1,5 cm de borde. Repartir la verdura y el pollo en una capa. Escurrir la mozzarella con papel de cocina, partirla en trozos de 1-2 cm y repartirla. Orégano y un hilo de aceite.","HORNEAR (12-15 min): meter la bandeja a altura media (segunda guía desde abajo). A los 7 minutos, con la manopla, darle media vuelta a la bandeja (180°) si el horno dora más por un lado. En total, 12-15 min, o el tiempo que indique el envase de la masa si es distinto.","COMPROBAR: está hecha cuando los bordes están dorados, la base está crujiente al levantar una esquina con la espátula y el queso está fundido y con burbujas. Si la base sigue blanda, 2-3 min más bajando la bandeja a la guía más baja.","REPOSAR Y CORTAR: sacar la bandeja con la manopla (quema mucho) y dejar reposar la pizza 2 minutos. Deslizarla con su papel a la tabla grande y cortarla en 8 porciones con el cortapizzas o un cuchillo grande."],"foto":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/2d/Kotipizza_Pollo_American_with_bell_pepper_and_one_edge_bent.jpg/330px-Kotipizza_Pollo_American_with_bell_pepper_and_one_edge_bent.jpg"}'::jsonb, 21, true),
  ('chef', 'recipe', 'macarrones-con-queso-gratinados-mac-cheese-casero', '{"n":"Macarrones con queso gratinados (mac & cheese casero)","pr":"Pasta","sana":"Moderado","dif":"Fácil","t":40,"val":"","com":"Variante: añade brócoli los últimos 3 minutos de cocción o taquitos de jamón a la salsa. El pimentón en el gratinado le da color y un punto ahumado.","cc":"Comida","rac":4,"cong":"Sí (mejor sin gratinar)","nev":"3","tm":"No","ut":"","ing":[["320 g","Macarrones"],["600 ml","Leche semidesnatada"],["40 g","Mantequilla"],["40 g","Harina"],["150 g","Cheddar"],["100 g","Mozzarella rallada"],["1 cdita","Mostaza suave"],["1/2 cdita","Pimentón dulce"],["25 g","Pan rallado"],["Al gusto","Nuez moscada"],["Al gusto","Sal y pimienta"]],"pasos":["COCER LOS MACARRONES: cocer los 320 g de macarrones.","BECHAMEL DE QUESO: con 40 g de mantequilla, 40 g de harina y 600 ml de leche semidesnatada, hacer la bechamel. Añadir 150 g de cheddar, 1 cdita de mostaza suave, la nuez moscada, sal y pimienta.","MEZCLAR: unir los macarrones con la bechamel de queso.","GRATINAR: con 100 g de mozzarella rallada, 25 g de pan rallado y 1/2 cdita de pimentón dulce, 10 min al horno a 200 °C y después 2–3 min de grill."],"foto":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/cc/Baked_macaroni_and_cheese.jpg/330px-Baked_macaroni_and_cheese.jpg"}'::jsonb, 22, true),
  ('chef', 'recipe', 'pollo-al-limon-y-ajo-con-arroz-basmati-y-calabacin-salteado', '{"n":"Pollo al limón y ajo con arroz basmati y calabacín salteado","pr":"Pollo","sana":"Sí","dif":"Fácil","t":35,"val":"","com":"Variante: cambia el calabacín por brócoli o pimiento. El pollo que sobre, frío y en tiras, sirve para un bowl o una ensalada.","cc":"Comida","rac":2,"cong":"Sí (pollo y arroz; el calabacín mejor recién hecho)","nev":"2","tm":"No","ut":"","ing":[["400 g","Pechuga"],["160 g","Arroz basmati"],["1","Calabacín"],["2","Ajos"],["1","Limón"],["2 cdas","Aceite de oliva"],["Al gusto","Orégano"],["Al gusto","Pimentón"],["Al gusto","Sal y pimienta"]],"pasos":["MARINAR: la pechuga en limón y ajo.","A LA SARTÉN: con 2 cdas de aceite de oliva, el orégano, el pimentón, sal y pimienta, hasta 74 °C con el termómetro.","ARROZ BASMATI: cocer los 160 g.","CALABACÍN: saltear el calabacín."],"foto":"https://upload.wikimedia.org/wikipedia/commons/thumb/d/d5/Chicken_and_Zucchini_dinner.jpg/330px-Chicken_and_Zucchini_dinner.jpg"}'::jsonb, 23, true),
  ('chef', 'recipe', 'salmon-al-horno-con-patatas-y-brocoli-en-una-sola-bandeja', '{"n":"Salmón al horno con patatas y brócoli en una sola bandeja","pr":"Salmón","sana":"Sí","dif":"Fácil","t":40,"val":"","com":"Variante: cambia el brócoli por calabacín o añade tomates cherry los últimos 10 min. Una cucharada de yogur con limón y ajo hace de salsa.","cc":"Cena","rac":2,"cong":"No","nev":"2","tm":"No","ut":"","ing":[["2 lomos (300 g)","Salmón"],["400 g","Patatas"],["1 pequeño","Brócoli"],["2","Ajos"],["1","Limón"],["2 cdas","Aceite de oliva"],["Al gusto","Pimentón"],["Al gusto","Orégano"],["Al gusto","Sal y pimienta"]],"pasos":["PATATAS: hornear las patatas 20 min a 210 °C.","TODO JUNTO: en la misma bandeja, los 2 lomos de salmón (300 g), el brócoli, los 2 ajos, el limón, 2 cdas de aceite de oliva, el pimentón, el orégano, sal y pimienta.","HORNEAR: 10–12 min más, hasta 63 °C con el termómetro."],"foto":"https://upload.wikimedia.org/wikipedia/commons/thumb/3/38/Liat_Portal_for_Foodie_Disorder_-_Oven-baked_teriyaki_salmon_with_vegetables.jpg/330px-Liat_Portal_for_Foodie_Disorder_-_Oven-baked_teriyaki_salmon_with_vegetables.jpg"}'::jsonb, 24, true),
  ('chef', 'recipe', 'ensalada-de-garbanzos-atun-huevo-y-tomate', '{"n":"Ensalada de garbanzos, atún, huevo y tomate","pr":"Garbanzo","sana":"Sí","dif":"Fácil","t":20,"val":"","com":"Variante: añade espinacas crudas o pepino, o cambia el atún por salmón o pollo que haya sobrado. Aliñada 10 minutos antes sabe mucho mejor.","cc":"Cena","rac":2,"cong":"No","nev":"2 (sin aliñar y con el huevo entero)","tm":"No","ut":"","ing":[["1 bote (400 g)","Garbanzos"],["2 latas","Atún al natural"],["2","Huevos"],["2","Tomates"],["1/2","Pimiento rojo"],["1/4","Cebolla"],["1/2","Limón"],["2 cdas","Aceite de oliva"],["Al gusto (opcional)","Comino"],["Al gusto","Sal y pimienta"]],"pasos":["HUEVOS: cocer los 2 huevos 10 min.","PICAR: los garbanzos del bote de 400 g, el atún de las 2 latas, los 2 tomates, 1/2 pimiento rojo y 1/4 de cebolla.","ALIÑAR: con 1/2 limón, 2 cdas de aceite de oliva, comino (opcional), sal y pimienta.","REPOSAR: 10 min."],"foto":"https://upload.wikimedia.org/wikipedia/commons/thumb/f/fb/Colorful_healthy_Chickpea_Salad_-_49859083608.jpg/330px-Colorful_healthy_Chickpea_Salad_-_49859083608.jpg"}'::jsonb, 25, true),
  ('chef', 'recipe', 'sandwich-club-de-pollo-huevo-y-tomate-con-salsa-de-yogur', '{"n":"Sándwich club de pollo, huevo y tomate con salsa de yogur","pr":"Pollo","sana":"Sí","dif":"Fácil","t":25,"val":"","com":"Variante: añade unas lonchas de jamón cocido o cambia la lechuga por espinacas frescas. Una pizca de ajo en polvo en la salsa de yogur la convierte en una salsa tipo César.","cc":"Cena","rac":2,"cong":"No (el pan se humedece y la lechuga y el tomate se estropean)","nev":"0 (al momento; el pollo cocinado aparte: 2 días)","tm":"No","ut":"Tabla y cuchillo · sartén antiadherente de 24-28 cm · cazo pequeño con tapa (huevos) · bol con agua fría · pinzas o espátula · tostadora (o la misma sartén) · vaso y cuchara (salsa) · palillos largos · plato llano · termómetro de cocina · temporizador.","ing":[["6 rebanadas","Pan de molde integral"],["1 pechuga (unos 250 g)","Pechuga de pollo"],["2","Huevos"],["1 grande (unos 200 g)","Tomate"],["4 hojas","Lechuga (romana o iceberg)"],["2 lonchas","Queso (cheddar o de lonchas)"],["1 yogur (125 g)","Yogur natural sin azúcar"],["1 cdita (5 g)","Mostaza suave"],["1/4","Limón (zumo)"],["1 cda (10 g)","Aceite de oliva virgen extra"],["1/2 cdita","Pimentón dulce"],["Al gusto","Sal y pimienta"]],"pasos":["HUEVOS: cocer los 2 huevos 10 min, enfriarlos y cortarlos en rodajas.","POLLO: abrir la pechuga (unos 250 g) en filetes, con sal, pimienta y 1/2 cdita de pimentón. Cocinarla en 1 cda de aceite hasta 74 °C en el centro y cortarla en tiras.","SALSA: mezclar 1 yogur (125 g), 1 cdita de mostaza, el zumo de 1/4 de limón y una pizca de sal. Lavar las 4 hojas de lechuga y cortar el tomate.","MONTAR: tostar las 6 rebanadas de pan. Pan con salsa, lechuga, tomate y pollo; otra rebanada con las 2 lonchas de queso y el huevo; tapar. Cortar en triángulos."],"foto":"https://upload.wikimedia.org/wikipedia/commons/thumb/d/dc/Club_sandwich%28including_egg%2C_ham%2C_chicken%29.jpg/330px-Club_sandwich%28including_egg%2C_ham%2C_chicken%29.jpg"}'::jsonb, 26, true),
  ('chef', 'recipe', 'sandwich-caliente-de-atun-tomate-y-mozzarella-fundida', '{"n":"Sándwich caliente de atún, tomate y mozzarella fundida","pr":"Atún","sana":"Moderado","dif":"Fácil","t":15,"val":"","com":"Variante: añade unas hojas de espinaca o unos pepinillos picados al relleno. Una pizca de pimentón en el atún le da un punto ahumado.","cc":"Cena","rac":2,"cong":"No (el pan se humedece)","nev":"0 (al momento; la mezcla de atún sin pan: 2 días)","tm":"No","ut":"Bol mediano · tenedor · abrelatas · tabla y cuchillo · sartén antiadherente de 28 cm con tapa · espátula ancha · cucharas medidoras · plato · temporizador.","ing":[["4 rebanadas","Pan de molde integral"],["2 latas pequeñas (unos 110 g escurrido)","Atún al natural"],["2 cdas (40 g)","Yogur natural sin azúcar"],["1 cdita (5 g)","Mostaza suave"],["1/4 (unos 40 g)","Cebolla"],["1 (unos 150 g)","Tomate"],["100 g","Mozzarella rallada"],["1 cda (10 g)","Aceite de oliva virgen extra (o 10 g de mantequilla)"],["1/4","Limón (zumo)"],["Al gusto","Sal, pimienta y orégano"]],"pasos":["RELLENO: mezclar el atún de las 2 latas con 2 cdas de yogur, 1 cdita de mostaza, el zumo de 1/4 de limón, 1/4 de cebolla picada, pimienta y orégano.","MONTAR: en 2 rebanadas, parte de los 100 g de mozzarella, el relleno, el tomate en rodajas y el resto de la mozzarella. Tapar con las otras 2 rebanadas y pintar por fuera con 1 cda de aceite.","DORAR: en la sartén tapada, hasta que el pan esté dorado por los dos lados y la mozzarella fundida. Cortar y servir."],"foto":"https://upload.wikimedia.org/wikipedia/commons/thumb/b/b0/Tuna_Melt_2.jpg/330px-Tuna_Melt_2.jpg"}'::jsonb, 27, true),
  ('chef', 'recipe', 'verduras-asadas-al-horno-con-huevo-a-la-plancha', '{"n":"Verduras asadas al horno con huevo a la plancha","pr":"Berenjena","sana":"Sí","dif":"Fácil","t":45,"val":"","com":"Variante: añade a la bandeja unos garbanzos cocidos escurridos (quedan crujientes) o pon unas migas de queso fresco al servir. Con las verduras sobrantes trituradas sale una crema.","cc":"Cena","rac":2,"cong":"No (las verduras asadas quedan aguadas)","nev":"3 (solo las verduras; el huevo, al momento)","tm":"No","ut":"Tabla y cuchillo · bandeja de horno grande · papel de horno · bol grande · espátula o pinzas · manoplas · sartén antiadherente de 24 cm (huevos) · vaso (aliño) · 2 platos · tartera hermética · temporizador.","ing":[["1 mediana (unos 300 g)","Berenjena"],["1 mediano (unos 300 g)","Calabacín"],["1 (unos 150 g)","Pimiento rojo"],["1 mediana (unos 150 g)","Cebolla"],["2 (unos 300 g)","Tomates"],["2 dientes","Ajo"],["4","Huevos"],["3 cdas (30 g)","Aceite de oliva virgen extra"],["1 cdita","Orégano o hierbas provenzales"],["1/2","Limón (zumo, para el aliño)"],["Al gusto","Sal y pimienta"]],"pasos":["CORTAR: la berenjena, el calabacín, el pimiento rojo, la cebolla y los 2 tomates, con los 2 dientes de ajo.","ASAR: con 2 cdas de aceite, 1 cdita de orégano, sal y pimienta, al horno a 210 °C hasta que la berenjena esté blanda y los bordes tostados.","ALIÑO: la cucharada de aceite que queda, el zumo de 1/2 limón, una pizca de sal y los ajos asados.","HUEVOS: los 4 huevos a la plancha hasta que la clara esté cuajada. Servir 2 por persona sobre las verduras."],"foto":"https://upload.wikimedia.org/wikipedia/commons/thumb/a/a4/Liat_Portal_for_Foodie_Disorder_-_Roasted_Antipasti_Vegetables.jpg/330px-Liat_Portal_for_Foodie_Disorder_-_Roasted_Antipasti_Vegetables.jpg"}'::jsonb, 28, true),
  ('chef', 'recipe', 'judias-verdes-con-patata-ajo-y-jamon', '{"n":"Judías verdes con patata, ajo y jamón","pr":"Judías verdes","sana":"Sí","dif":"Fácil","t":30,"val":"","com":"Variante: sin jamón y con un huevo a la plancha queda vegetariano. Unas gotas de vinagre al final avivan mucho el sabor.","cc":"Cena","rac":2,"cong":"No (la patata cocida se vuelve harinosa)","nev":"3","tm":"No","ut":"Tabla y cuchillo · pelador · olla mediana de 3 L con tapa · colador grande · sartén de 28 cm · cuchara de madera · tenedor (probar la patata) · 2 platos · tartera hermética · temporizador.","ing":[["400 g","Judías verdes planas (frescas o congeladas)"],["2 medianas (unos 350 g)","Patatas"],["3 dientes","Ajo"],["60 g (taquitos)","Jamón serrano en taquitos"],["2 cdas (20 g)","Aceite de oliva virgen extra"],["1/2 cdita","Pimentón dulce"],["2 litros + 1 cdita (5 g) de sal","Agua para cocer"],["Al gusto","Sal"]],"pasos":["COCER: las patatas (unos 350 g) y las 400 g de judías verdes en el agua con sal, hasta que la patata esté tierna y la judía siga de un verde intenso.","REHOGAR: 2 cdas de aceite con los 3 dientes de ajo laminados y los 60 g de jamón, sin que el ajo se dore de más.","SALTEAR: fuera del fuego, 1/2 cdita de pimentón y enseguida las judías y la patata. Probar de sal."],"foto":"https://upload.wikimedia.org/wikipedia/commons/thumb/7/75/Jud%C3%ADas_verdes_cocidas_salteadas_con_jam%C3%B3n_serrano.jpg/330px-Jud%C3%ADas_verdes_cocidas_salteadas_con_jam%C3%B3n_serrano.jpg"}'::jsonb, 29, true),
  ('chef', 'recipe', 'ensalada-de-lentejas-con-pimiento-tomate-pepino-y-huevo', '{"n":"Ensalada de lentejas con pimiento, tomate, pepino y huevo","pr":"Lenteja","sana":"Sí","dif":"Fácil","t":20,"val":"","com":"Variante: añade una lata de atún escurrido o unos dados de queso fresco. Con un poco de zanahoria rallada gana color y un toque dulce.","cc":"Cena","rac":2,"cong":"No (el tomate, el pepino y el huevo cocido se estropean)","nev":"2 (sin aliñar; el huevo, entero y con cáscara)","tm":"No","ut":"Cazo pequeño con tapa (huevos) · cuchara (bajar los huevos) · bol con agua fría · colador · tabla y cuchillo · ensaladera o bol grande · exprimidor · vaso y tenedor (aliño) · cucharas medidoras · 2 platos · tarteras herméticas (para llevar) · temporizador.","ing":[["1 bote de 400 g (unos 250 g escurridas)","Lentejas cocidas"],["2","Huevos"],["1 (unos 150 g)","Pimiento rojo"],["2 (unos 300 g)","Tomates"],["1/2 (unos 150 g)","Pepino"],["1/4 (unos 40 g)","Cebolla"],["1/2","Limón (zumo)"],["2 cdas (20 g)","Aceite de oliva virgen extra"],["1/2 cdita","Comino molido (o pimentón dulce)"],["Al gusto","Sal y pimienta"]],"pasos":["HUEVOS: cocer los 2 huevos 10 min, enfriarlos y cortarlos en cuartos.","PICAR: escurrir las lentejas del bote de 400 g. Cortar el pimiento, los 2 tomates, 1/2 pepino y 1/4 de cebolla.","ALIÑAR: 2 cdas de aceite, el zumo de 1/2 limón, 1/2 cdita de comino, sal y pimienta. Mezclar con las lentejas y reposar 10 min.","SERVIR: con el huevo por encima."],"foto":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/ee/Lentil_salad_with_black_olives%2C_carrot%2C_tomatoand_red_pepper_%287520199672%29.jpg/330px-Lentil_salad_with_black_olives%2C_carrot%2C_tomatoand_red_pepper_%287520199672%29.jpg"}'::jsonb, 30, true),
  ('chef', 'recipe', 'ensalada-campera-patata-huevo-pimiento-y-atun', '{"n":"Ensalada campera (patata, huevo, pimiento y atún)","pr":"Patata","sana":"Sí","dif":"Fácil","t":35,"val":"","com":"Variante: añade unas aceitunas o cambia el atún por salmón o merluza que haya sobrado. Con pepino en dados queda más fresca.","cc":"Cena","rac":2,"cong":"No (la patata cocida y el huevo se estropean)","nev":"2","tm":"No","ut":"Olla mediana de 3 L con tapa · cuchara (bajar los huevos) · bol con agua fría · colador · abrelatas · tabla y cuchillo · pelador · tenedor (probar la patata) · ensaladera o bol grande · vaso (aliño) · 2 platos · tartera hermética · temporizador.","ing":[["3 medianas (unos 500 g)","Patatas"],["2","Huevos"],["1 lata pequeña (unos 55 g escurrido)","Atún al natural"],["1/2 (unos 75 g)","Pimiento rojo"],["1/2 (unos 75 g)","Pimiento verde"],["1 (unos 150 g)","Tomate"],["1/4 (unos 40 g)","Cebolla"],["3 cdas (30 g)","Aceite de oliva virgen extra"],["1 cda (15 ml)","Vinagre de vino"],["2 litros + 1 cdita (5 g) de sal","Agua para cocer"],["Al gusto","Sal y pimienta"]],"pasos":["COCER: las patatas (unos 500 g) y los 2 huevos en el agua con sal. Sacar los huevos a los 10 min; las patatas, cuando el tenedor entre sin que se deshagan.","PICAR: 1/2 pimiento rojo, 1/2 pimiento verde, el tomate y 1/4 de cebolla. Escurrir el atún de la lata.","ALIÑAR: la patata templada con 3 cdas de aceite, 1 cda de vinagre, sal y pimienta.","SERVIR: el atún y el huevo en cuartos por encima."],"foto":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/e3/Ensalada_campera%2C_gastronom%C3%ADa_de_Espa%C3%B1a.jpg/330px-Ensalada_campera%2C_gastronom%C3%ADa_de_Espa%C3%B1a.jpg"}'::jsonb, 31, true),
  ('chef', 'recipe', 'hamburguesa-clasica-de-ternera-con-queso-cebolla-y-tomate', '{"n":"Hamburguesa clásica de ternera con queso, cebolla y tomate","pr":"Ternera picada","sana":"Moderado","dif":"Fácil","t":30,"val":"","com":"Variante: añade un huevo a la plancha encima o unas tiras de pimiento asado. La cebolla caramelizada se puede hacer el doble y guardar 4 días en la nevera.","cc":"Cena","rac":2,"cong":"Sí (las hamburguesas crudas, separadas con papel de horno)","nev":"1 (cocinadas; crudas formadas: 1 día)","tm":"No","ut":"Bol grande · tabla y cuchillo · sartén de 28 cm (o plancha) · sartén pequeña (cebolla) · espátula ancha · papel de horno · plato llano · báscula · termómetro de cocina · temporizador.","ing":[["400 g","Carne picada de ternera (o mixta ternera-cerdo)"],["2","Panes de hamburguesa (mejor tipo brioche)"],["2 lonchas","Queso cheddar"],["1 mediana (unos 150 g)","Cebolla"],["1 (unos 150 g)","Tomate"],["4 hojas","Lechuga"],["1 cdita (5 g)","Mostaza"],["2 cdas (30 g)","Kétchup (o tomate triturado reducido)"],["1 cda (10 g)","Aceite de oliva virgen extra"],["1/2 cdita","Sal (solo justo antes de cocinar)"],["Al gusto","Pimienta negra molida"]],"pasos":["CEBOLLA: la cebolla (unos 150 g) en tiras, con un poco del aceite, hasta que esté blanda y dorada.","FORMAR: los 400 g de ternera picada en 2 hamburguesas. Sal y pimienta justo antes de la sartén.","COCINAR: en el resto de la cucharada de aceite, hasta 74 °C en el centro. Al final, las 2 lonchas de cheddar para que se fundan.","MONTAR: los 2 panes tostados, con mostaza, lechuga, tomate, hamburguesa, cebolla y kétchup."],"foto":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/22/Homemade_cheeseburger.jpg/330px-Homemade_cheeseburger.jpg"}'::jsonb, 32, true),
  ('chef', 'recipe', 'hamburguesa-de-pollo-y-calabacin-con-salsa-de-yogur', '{"n":"Hamburguesa de pollo y calabacín con salsa de yogur","pr":"Pollo","sana":"Sí","dif":"Fácil","t":35,"val":"","com":"Variante: cambia el calabacín por zanahoria rallada o añade una cucharadita de curry suave a la mezcla. Con la salsa de yogur y un poco de ajo picado queda tipo kebab.","cc":"Cena","rac":2,"cong":"Sí (crudas, separadas con papel de horno)","nev":"1 (cocinadas; crudas formadas: 1 día)","tm":"Sí (para picar el pollo; opcional si se compra picado)","ut":"Thermomix (o picadora / cuchillo grande) · rallador de agujero grueso · paño limpio (escurrir el calabacín) · bol grande · tabla y cuchillo · sartén antiadherente de 28 cm con tapa · espátula ancha · papel de horno · vaso (salsa) · báscula · termómetro de cocina · temporizador.","ing":[["400 g","Pechuga de pollo (o pollo picado)"],["1/2 (unos 150 g)","Calabacín"],["1 diente","Ajo"],["3 cdas (25 g)","Pan rallado"],["1","Huevo"],["2","Panes de hamburguesa (integrales si hay)"],["1 (unos 150 g)","Tomate"],["4 hojas","Lechuga"],["1 yogur (125 g)","Yogur natural sin azúcar"],["1/4","Limón (zumo)"],["1/2 cdita","Pimentón dulce"],["1 cda (10 g)","Aceite de oliva virgen extra"],["Al gusto","Sal y pimienta"]],"pasos":["PICAR: los 400 g de pechuga con 1 diente de ajo (Thermomix, o pollo ya picado). Rallar 1/2 calabacín y escurrirlo bien.","MEZCLAR: pollo, calabacín, 1 huevo, 3 cdas de pan rallado, 1/2 cdita de pimentón, sal y pimienta. Formar 2 hamburguesas.","SALSA: 1 yogur (125 g) con el zumo de 1/4 de limón y una pizca de sal. Cortar el tomate y lavar la lechuga.","COCINAR: en 1 cda de aceite hasta 74 °C en el centro, por dentro blanca. Montar los panes con salsa, lechuga, hamburguesa y tomate."],"foto":"https://upload.wikimedia.org/wikipedia/commons/thumb/a/a4/Chargrilled_Chicken_Burger_-_Leon.jpg/330px-Chargrilled_Chicken_Burger_-_Leon.jpg"}'::jsonb, 33, true),
  ('chef', 'recipe', 'hamburguesa-de-salmon-con-salsa-de-yogur-y-limon', '{"n":"Hamburguesa de salmón con salsa de yogur y limón","pr":"Salmón","sana":"Sí","dif":"Fácil","t":30,"val":"","com":"Variante: añade a la salsa de yogur un poco de eneldo o pepino rallado (tipo tzatziki). También se puede servir sin pan, con ensalada o arroz basmati.","cc":"Cena","rac":2,"cong":"Sí (crudas, separadas con papel de horno)","nev":"1 (cocinadas; crudas formadas: 1 día)","tm":"No (a cuchillo queda mejor textura)","ut":"Tabla y cuchillo grande bien afilado · bol grande · rallador fino · sartén antiadherente de 28 cm · espátula ancha · papel de horno · papel de cocina · vaso (salsa) · báscula · termómetro de cocina · temporizador.","ing":[["350 g","Lomo de salmón sin piel ni espinas (fresco o congelado y descongelado)"],["1/4 (unos 40 g)","Cebolla (o cebolleta)"],["1","Huevo"],["3 cdas (25 g)","Pan rallado"],["1","Limón (ralladura de medio + zumo)"],["1 cdita (5 g)","Mostaza"],["2","Panes de hamburguesa (integrales si hay)"],["1/2 (unos 150 g)","Pepino"],["4 hojas","Lechuga"],["1 yogur (125 g)","Yogur natural sin azúcar"],["1 cda (10 g)","Aceite de oliva virgen extra"],["Al gusto","Sal y pimienta"]],"pasos":["PICAR: los 350 g de salmón con 1/4 de cebolla, 1 huevo, 3 cdas de pan rallado, 1 cdita de mostaza, la ralladura de medio limón, sal y pimienta. Formar 2 hamburguesas.","SALSA: 1 yogur (125 g) con el zumo de medio limón y una pizca de sal. Cortar 1/2 pepino y lavar la lechuga.","COCINAR: en 1 cda de aceite hasta 63 °C en el centro, rosa claro y opaco.","MONTAR: los panes, la salsa, la lechuga, la hamburguesa y el pepino."],"foto":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/24/Salmon_burger.jpg/330px-Salmon_burger.jpg"}'::jsonb, 34, true),
  ('chef', 'recipe', 'pollo-crujiente-con-miel-soja-y-ajo-con-arroz-basmati', '{"n":"Pollo crujiente con miel, soja y ajo con arroz basmati","pr":"Pollo","sana":"Moderado","dif":"Fácil","t":35,"val":"","com":"Variante: añade a la salsa una pizca de guindilla para un punto picante, o saltea unos ramilletes de brócoli en la sartén antes del pollo y sírvelos con la salsa.","cc":"Cena","rac":2,"cong":"Sí (pollo con salsa y arroz; pierde lo crujiente)","nev":"2","tm":"No","ut":"Tabla y cuchillo · olla mediana de 3 L con tapa (arroz) · colador · bol grande · sartén antiadherente de 28 cm · pinzas o espátula · vaso y cuchara (salsa) · rallador fino · plato con papel de cocina · cucharas medidoras · termómetro de cocina · temporizador.","ing":[["400 g","Contramuslos de pollo sin piel ni hueso (o pechuga)"],["3 cdas (25 g)","Maicena (harina fina de maíz)"],["3 cdas (45 ml)","Salsa de soja"],["2 cdas (40 g)","Miel"],["3 dientes","Ajo"],["1 trozo de 2 cm (opcional)","Jengibre fresco"],["1 cda (15 ml)","Vinagre (de arroz o de vino) o zumo de limón"],["3 cdas (30 g)","Aceite de oliva suave o girasol"],["160 g","Arroz basmati"],["1,5 litros + 1 cdita de sal","Agua para cocer el arroz"],["1 (opcional)","Cebolleta (lo verde, en aros) o sésamo"],["Al gusto","Sal y pimienta"]],"pasos":["ARROZ: cocer los 160 g de arroz basmati en el agua con sal.","REBOZAR: los 400 g de pollo en dados, con sal, pimienta y 3 cdas de maicena. Dorarlos en 3 cdas de aceite hasta 74 °C en el centro del trozo más grueso.","SALSA: 3 cdas de soja, 2 cdas de miel, 1 cda de vinagre, los 3 dientes de ajo y el jengibre (opcional). Glasear el pollo con esa salsa.","SERVIR: el pollo sobre el arroz, con la cebolleta o el sésamo (opcional)."],"foto":"https://upload.wikimedia.org/wikipedia/commons/thumb/7/7a/Thai_Fried_Chicken_2026-10-20_honey_glazed.jpg/330px-Thai_Fried_Chicken_2026-10-20_honey_glazed.jpg"}'::jsonb, 35, true),
  ('chef', 'recipe', 'gambas-al-ajillo-con-guindilla-y-pan-tostado', '{"n":"Gambas al ajillo con guindilla y pan tostado","pr":"Gamba","sana":"Sí","dif":"Fácil","t":15,"val":"","com":"Variante: con el aceite y las gambas que sobren, mezcla 160 g de espaguetis recién cocidos y tienes una pasta al ajillo. Un chorrito de vino blanco al final le da el punto de bar.","cc":"Cena","rac":2,"cong":"No (la gamba cocinada se queda dura)","nev":"0 (al momento)","tm":"No","ut":"Cazuela de barro o sartén pequeña de 20-24 cm · tabla y cuchillo · papel de cocina · cuchara de madera · tostadora (o sartén) · cucharas medidoras · termómetro de cocina · temporizador.","ing":[["300 g","Gambas peladas crudas (congeladas, descongeladas en la nevera)"],["5 dientes","Ajo"],["1 (o 1/2 cdita en copos)","Guindilla seca"],["6 cdas (60 ml)","Aceite de oliva virgen extra"],["1 pizca","Pimentón dulce (opcional)"],["1 puñado (opcional)","Perejil fresco picado"],["1/2 barra (unos 125 g)","Pan de barra para mojar"],["Al gusto","Sal gorda o normal"]],"pasos":["PREPARAR: secar bien las 300 g de gambas y salarlas. Laminar los 5 dientes de ajo y trocear la guindilla. Tostar 1/2 barra de pan.","AJO: los ajos y la guindilla en las 6 cdas de aceite, hasta que el ajo esté dorado claro y no oscuro.","GAMBAS: cocinarlas hasta que estén rosadas, opacas y curvadas, a 63 °C en la parte más gruesa. Añadir el pimentón y el perejil (opcionales) y servir con el pan."],"foto":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/65/Gambas_al_ajillo.jpg/330px-Gambas_al_ajillo.jpg"}'::jsonb, 36, true),
  ('chef', 'recipe', 'pasta-cremosa-de-chorizo-tomate-y-queso', '{"n":"Pasta cremosa de chorizo, tomate y queso","pr":"Pasta","sana":"Moderado","dif":"Fácil","t":25,"val":"","com":"Variante: añade medio pimiento rojo en tiras con la cebolla o unos guisantes congelados con el tomate. Con chorizo picante y una pizca de guindilla queda tipo arrabbiata.","cc":"Cena","rac":2,"cong":"No (la pasta se ablanda y la salsa se corta)","nev":"2","tm":"No","ut":"Olla grande de 4 L con tapa · colador · taza (reservar agua de la pasta) · tabla y cuchillo · sartén honda de 28 cm · cuchara de madera · rallador · cucharas medidoras · 2 platos · temporizador.","ing":[["200 g","Pasta corta (macarrones, penne o rigatoni)"],["100 g","Chorizo (tipo sarta, dulce o picante)"],["1/2 (unos 75 g)","Cebolla"],["2 dientes","Ajo"],["200 g (4 cdas colmadas)","Tomate triturado"],["100 ml","Nata ligera para cocinar (o 100 g de queso crema)"],["40 g","Queso rallado (curado o parmesano tipo grana)"],["1 puñado (unos 40 g, opcional)","Espinacas frescas"],["3 litros + 1 cda (15 g) de sal","Agua para cocer la pasta"],["Al gusto","Pimienta negra molida"]],"pasos":["COCER: los 200 g de pasta en el agua con sal.","CHORIZO: los 100 g en rodajas, sin aceite, hasta que suelten su grasa. Si el chorizo es fresco, 74 °C en el centro. Añadir 1/2 cebolla y 2 dientes de ajo hasta que la cebolla esté blanda.","SALSA: 200 g de tomate triturado y, después, 100 ml de nata, sin que hierva fuerte.","MEZCLAR: la pasta con la salsa, la mitad de los 40 g de queso y las espinacas (opcional). Servir con el resto del queso y pimienta."],"foto":"https://upload.wikimedia.org/wikipedia/commons/thumb/d/d6/Chorizo_Pasta_Bake_%2825966929%29.jpeg/330px-Chorizo_Pasta_Bake_%2825966929%29.jpeg"}'::jsonb, 37, true),
  ('chef', 'recipe', 'arroz-seco-de-pollo-y-verduras-en-sarten-tipo-paella', '{"n":"Arroz seco de pollo y verduras en sartén (tipo paella)","pr":"Arroz redondo","sana":"Sí","dif":"Media","t":50,"val":"","com":"Variante: cambia las judías por alcachofa en cuartos o guisantes. Un poco de alioli al servir y el socarrat del fondo son lo más rico.","cc":"Comida","rac":2,"cong":"No (el arroz se pasa y queda blando)","nev":"1","tm":"No","ut":"Paellera de 34-38 cm o sartén grande de 28-32 cm (sin tapa) · tabla y cuchillo · cazo con el caldo · taza medidora · báscula · cuchara de madera · paño limpio de cocina (reposo) · termómetro de cocina · temporizador.","ing":[["160 g","Arroz redondo (o bomba) — 80 g por persona"],["550 ml","Caldo de pollo (de brik o casero); proporción 1 arroz : 3,4 caldo en volumen aprox. (3 veces y media su volumen con bomba)"],["400 g","Contramuslos de pollo sin piel en trozos de 3-4 cm"],["1/2 (unos 75 g)","Pimiento rojo"],["100 g","Judías verdes planas (frescas o congeladas)"],["2 dientes","Ajo"],["2 cdas (40 g)","Tomate triturado"],["1 cdita (3 g)","Pimentón dulce"],["1 sobre (0,1 g) o 1 pizca","Colorante alimentario o azafrán"],["3 cdas (30 g)","Aceite de oliva virgen extra"],["1/2","Limón (en gajos, al servir)"],["Al gusto","Sal (unos 1/2 cdita, según el caldo)"]],"pasos":["DORAR: los 400 g de pollo en trozos con las 3 cdas de aceite.","SOFRITO: 1/2 pimiento rojo, 100 g de judías verdes, 2 dientes de ajo, 2 cdas de tomate triturado y 1 cdita de pimentón.","ARROZ: nacarar los 160 g de arroz redondo, verter los 550 ml de caldo caliente y el colorante o el azafrán. Repartir una vez y no volver a remover.","TERMINAR: el pollo tiene que llegar a 74 °C en el centro del trozo más grueso. Servir con 1/2 limón."],"foto":"https://upload.wikimedia.org/wikipedia/commons/thumb/3/35/Arroz_con_pollo_pa.jpeg/330px-Arroz_con_pollo_pa.jpeg"}'::jsonb, 38, true),
  ('chef', 'recipe', 'arroz-de-gambas-al-pimenton-en-sarten', '{"n":"Arroz de gambas al pimentón en sartén","pr":"Arroz redondo","sana":"Sí","dif":"Media","t":40,"val":"","com":"Variante: añade 100 g de calamar en anillas con el sofrito o unos guisantes con el caldo. Con alioli al lado está de restaurante.","cc":"Comida","rac":2,"cong":"No (el arroz y la gamba se estropean)","nev":"1","tm":"No","ut":"Paellera de 34-38 cm o sartén grande de 28-32 cm (sin tapa) · tabla y cuchillo · cazo con el caldo · taza medidora · báscula · cuchara de madera · plato (reservar gambas) · papel de cocina · paño limpio de cocina (reposo) · termómetro de cocina · temporizador.","ing":[["160 g","Arroz redondo (o bomba) — 80 g por persona"],["550 ml","Caldo de pescado o marisco (de brik); con bomba, 600 ml"],["250 g","Gambas peladas crudas (congeladas, descongeladas en la nevera)"],["1/2 (unos 75 g)","Pimiento rojo"],["1/2 (unos 75 g)","Cebolla"],["3 dientes","Ajo"],["3 cdas (60 g)","Tomate triturado"],["1 cdita colmada (4 g)","Pimentón dulce (o mitad ahumado)"],["1 sobre (0,1 g) o 1 pizca","Colorante alimentario o azafrán"],["3 cdas (30 g)","Aceite de oliva virgen extra"],["1/2","Limón (en gajos)"],["Al gusto","Sal"]],"pasos":["MARCAR: las 250 g de gambas, secas y con sal, en un poco de las 3 cdas de aceite. Apartarlas.","SOFRITO: 1/2 pimiento, 1/2 cebolla, 3 dientes de ajo, 3 cdas de tomate triturado y 1 cdita de pimentón, con el resto del aceite.","ARROZ: nacarar los 160 g de arroz redondo, verter los 550 ml de caldo caliente y el colorante o el azafrán. Repartir una vez y no volver a remover.","GAMBAS: incorporarlas al final, hasta 63 °C en la parte más gruesa, rosadas y opacas. Servir con 1/2 limón."],"foto":"https://upload.wikimedia.org/wikipedia/commons/thumb/1/14/Paella_receta_personal.jpg/330px-Paella_receta_personal.jpg"}'::jsonb, 39, true),
  ('chef', 'recipe', 'arroz-meloso-de-champinones-y-queso-en-sarten', '{"n":"Arroz meloso de champiñones y queso en sartén","pr":"Arroz redondo","sana":"Sí","dif":"Fácil","t":35,"val":"","com":"Variante: añade unos taquitos de jamón con el sofrito o unas tiras de pollo sobrante al final. Un hilo de aceite de trufa (opcional) lo convierte en plato de fiesta.","cc":"Cena","rac":2,"cong":"No (el arroz se pasa)","nev":"1","tm":"No","ut":"Sartén honda de 28 cm (o paellera) · cazo con el caldo · cucharón · tabla y cuchillo · cuchara de madera · rallador · taza medidora · báscula · temporizador.","ing":[["160 g","Arroz redondo (o bomba) — 80 g por persona"],["800 ml","Caldo de verduras o de pollo (de brik) — proporción 1 : 5 para meloso"],["250 g","Champiñón laminado"],["1/2 (unos 75 g)","Cebolla"],["2 dientes","Ajo"],["1 puñado (40 g, opcional)","Espinacas frescas"],["40 g","Queso rallado (curado o tipo grana)"],["15 g","Mantequilla (o 1 cda de aceite)"],["2 cdas (20 g)","Aceite de oliva virgen extra"],["50 ml (opcional)","Vino blanco"],["Al gusto","Sal y pimienta"]],"pasos":["CHAMPIÑONES: los 250 g con una parte de las 2 cdas de aceite, hasta que se doren.","SOFRITO: 1/2 cebolla y 2 dientes de ajo con el resto del aceite. Nacarar los 160 g de arroz. Si se usa, los 50 ml de vino blanco.","COCER: añadir los 800 ml de caldo caliente poco a poco, removiendo, hasta que el grano esté tierno y el conjunto quede cremoso. Incorporar las espinacas (opcional).","MANTECAR: fuera del fuego, 15 g de mantequilla y 40 g de queso rallado. Servir con pimienta."],"foto":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/58/Mushroom_Risotto_%284789409441%29.jpg/330px-Mushroom_Risotto_%284789409441%29.jpg"}'::jsonb, 40, true),
  ('chef', 'recipe', 'lentejas-pardinas-con-chorizo-y-verduras-en-olla-expres', '{"n":"Lentejas pardinas con chorizo y verduras en olla exprés","pr":"Lenteja","sana":"Moderado","dif":"Fácil","t":40,"val":"","com":"Al día siguiente están todavía mejor. Para menos grasa, dora el chorizo 2 min, retira parte del aceite y sigue. Variante: media morcilla los últimos 5 min sin presión.","cc":"Comida","rac":4,"cong":"Sí","nev":"4","tm":"No","ut":"Olla exprés de 6 L (con válvula o indicador de anillos) · tabla y cuchillo · pelador · cuchara de madera · colador · jarra medidora · báscula · temporizador · cucharón","ing":[["300 g","Lenteja pardina (sin remojo) — 75 g por persona"],["840 ml","Agua o caldo de verduras (2,8 ml por gramo de lenteja)"],["150 g","Chorizo curado para guisar (1 sarta pequeña)"],["1 (unos 150 g)","Cebolla"],["2","Zanahorias (unos 150 g)"],["1/2 (unos 100 g)","Pimiento verde"],["2 dientes","Ajo"],["1 (unos 200 g)","Patata mediana"],["1","Tomate maduro rallado (o 100 g tomate triturado)"],["1 cdta","Pimentón dulce de la Vera"],["1","Hoja de laurel"],["2 cdas (20 g)","Aceite de oliva virgen extra · sal"]],"pasos":["SOFRITO: con 2 cdas de aceite, dorar 150 g de chorizo. Añadir 1 cebolla (unos 150 g), 1/2 pimiento verde (unos 100 g), 2 zanahorias (unos 150 g) y 2 dientes de ajo. Al final, 1 tomate.","OLLA: 300 g de lentejas pardinas, 1 patata (unos 200 g), 1 cdta de pimentón, 1 hoja de laurel, 1 cdta de sal (5 g) y 840 ml de agua.","PRESIÓN: 9 min a presión alta desde que sube la válvula. Despresurizar 10 min y reposar 5 min."],"foto":"https://upload.wikimedia.org/wikipedia/commons/thumb/b/b3/Guiso_de_lentejas_argentino_con_chorizo_y_verduras_cocidas_lentamente.jpg/330px-Guiso_de_lentejas_argentino_con_chorizo_y_verduras_cocidas_lentamente.jpg"}'::jsonb, 41, true),
  ('chef', 'recipe', 'lentejas-pardinas-vegetales-con-calabaza-y-espinacas-en-olla-expres', '{"n":"Lentejas pardinas vegetales con calabaza y espinacas en olla exprés","pr":"Lenteja","sana":"Sí","dif":"Fácil","t":40,"val":"","com":"Plato completo vegetal: la calabaza se deshace en parte y deja un caldo dulce y espeso. Variante: un huevo cocido picado por encima o boniato en vez de calabaza.","cc":"Comida","rac":4,"cong":"Sí","nev":"4","tm":"No","ut":"Olla exprés de 6 L (con válvula o indicador de anillos) · tabla y cuchillo · pelador · cuchara de madera · colador · jarra medidora · báscula · temporizador · cucharón","ing":[["300 g","Lenteja pardina (sin remojo) — 75 g por persona"],["840 ml","Agua o caldo de verduras (2,8 ml por gramo de lenteja)"],["300 g (pelada)","Calabaza"],["100 g","Espinacas frescas (2 puñados grandes)"],["1 (unos 150 g)","Cebolla"],["1 (unos 100 g)","Zanahoria"],["2 dientes","Ajo"],["1","Tomate rallado (o 100 g triturado)"],["1 cdta + 1/2 cdta","Pimentón dulce + comino molido"],["1","Hoja de laurel"],["2 cdas (20 g)","Aceite de oliva virgen extra · sal"]],"pasos":["SOFRITO: 2 cdas de aceite con 1 cebolla (unos 150 g), 1 zanahoria (unos 100 g) y 2 dientes de ajo. Luego 1 tomate.","ESPECIAS: fuera del fuego, 1 cdta de pimentón y 1/2 cdta de comino.","OLLA: 300 g de lentejas pardinas, 300 g de calabaza, 1 hoja de laurel, 1 cdta de sal (5 g) y 840 ml de agua. Presión alta 9 min y despresurizar 10 min.","ESPINACAS: abrir y añadir 100 g de espinacas. Reposar 5 min."],"foto":"https://upload.wikimedia.org/wikipedia/commons/thumb/a/a4/Catalan_lentil_soup.JPG/330px-Catalan_lentil_soup.JPG"}'::jsonb, 42, true),
  ('chef', 'recipe', 'lentejas-pardinas-al-curry-suave-con-zanahoria-en-olla-expres', '{"n":"Lentejas pardinas al curry suave con zanahoria en olla exprés","pr":"Lenteja","sana":"Sí","dif":"Fácil","t":40,"val":"","com":"Tipo dal: queda cremoso y aromático sin picar. Acompaña con 2 cdas de arroz basmati o una tortilla de trigo tostada. Variante: garbanzos cocidos o dados de pollo ya cocinado al final.","cc":"Cena","rac":4,"cong":"Sí","nev":"4","tm":"No","ut":"Olla exprés de 6 L (con válvula o indicador de anillos) · tabla y cuchillo · pelador · cuchara de madera · colador · jarra medidora · báscula · temporizador · cucharón","ing":[["300 g","Lenteja pardina (sin remojo) — 75 g por persona"],["700 ml + 140 ml","Agua o caldo de verduras + leche de coco ligera (total 840 ml = 2,8 ml/g)"],["3 (unos 250 g)","Zanahorias"],["1 (unos 150 g)","Cebolla"],["2 dientes","Ajo"],["1 trozo de 2 cm (o 1/2 cdta molido)","Jengibre"],["200 g","Tomate triturado"],["2 cdtas (6 g)","Curry suave en polvo"],["1/2 cdta","Comino molido"],["1 puñado (40 g)","Espinacas frescas (opcional)"],["1/2","Limón (zumo)"],["2 cdas (20 g)","Aceite de oliva virgen extra · sal"]],"pasos":["SOFRITO: 2 cdas de aceite, 1 cebolla (unos 150 g), 3 zanahorias (unos 250 g), 2 dientes de ajo y el jengibre. Añadir 200 g de tomate triturado.","ESPECIAS: 2 cdtas de curry y 1/2 cdta de comino.","OLLA: 300 g de lentejas pardinas, 1 cdta de sal (5 g) y 700 ml de agua o caldo. Presión alta 9 min y despresurizar 10 min.","COCO: 140 ml de leche de coco, 40 g de espinacas (opcional) y el zumo de 1/2 limón. Reposar 5 min."],"foto":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/97/Curried_Lentil_Soup_%2825031652894%29.jpg/330px-Curried_Lentil_Soup_%2825031652894%29.jpg"}'::jsonb, 43, true),
  ('chef', 'recipe', 'lentejas-pardinas-con-arroz-y-pimiento-en-olla-expres', '{"n":"Lentejas pardinas con arroz y pimiento en olla exprés","pr":"Lenteja","sana":"Sí","dif":"Fácil","t":40,"val":"","com":"Clásico de cuchara completo (legumbre + cereal). No se congela porque el arroz se queda blando. Variante: una morcilla o chorizo en rodajas con el sofrito si quieres un día más contundente.","cc":"Comida","rac":4,"cong":"No (el arroz se pasa)","nev":"3","tm":"No","ut":"Olla exprés de 6 L (con válvula o indicador de anillos) · tabla y cuchillo · pelador · cuchara de madera · colador · jarra medidora · báscula · temporizador · cucharón","ing":[["300 g","Lenteja pardina (sin remojo)"],["80 g","Arroz redondo"],["840 ml + 200 ml","Agua o caldo (840 ml = 2,8 ml/g de lenteja + 200 ml para el arroz ≈ 2,5 ml/g)"],["1 (unos 150 g)","Pimiento rojo"],["1/2 (unos 100 g)","Pimiento verde"],["1 (unos 150 g)","Cebolla"],["1 (unos 100 g)","Zanahoria"],["2 dientes","Ajo"],["1","Tomate rallado (o 100 g triturado)"],["1 cdta","Pimentón dulce"],["1","Hoja de laurel"],["2 cdas (20 g)","Aceite de oliva virgen extra · sal"]],"pasos":["SOFRITO: 2 cdas de aceite, 1 pimiento rojo (unos 150 g), 1/2 pimiento verde (unos 100 g), 1 cebolla (unos 150 g), 1 zanahoria (unos 100 g), 2 dientes de ajo y 1 tomate.","OLLA: 300 g de lentejas pardinas, 80 g de arroz redondo, 1 cdta de pimentón, 1 hoja de laurel, 1 cdta de sal (6 g), 840 ml de agua para las lentejas y 200 ml más para el arroz.","PRESIÓN: 9 min a presión alta desde que sube la válvula. Despresurizar 10 min y reposar 5 min."],"foto":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/2f/Lentejas_con_arroz%2C_gastronom%C3%ADa_de_Espa%C3%B1a.jpg/330px-Lentejas_con_arroz%2C_gastronom%C3%ADa_de_Espa%C3%B1a.jpg"}'::jsonb, 44, true),
  ('chef', 'recipe', 'lentejas-pardinas-guisadas-con-pollo-y-verduras-en-olla-expres', '{"n":"Lentejas pardinas guisadas con pollo y verduras en olla exprés","pr":"Lenteja","sana":"Sí","dif":"Fácil","t":45,"val":"","com":"Muy completo y suave, gusta a todos. Variante con costilla de cerdo: 400 g en trozos, dorar igual, 12 min de presión en vez de 9 y comprobar 71 °C junto al hueso.","cc":"Comida","rac":4,"cong":"Sí","nev":"3","tm":"No","ut":"Olla exprés de 6 L (con válvula o indicador de anillos) · tabla y cuchillo · pelador · cuchara de madera · colador · jarra medidora · báscula · temporizador · cucharón · termómetro de cocina","ing":[["300 g","Lenteja pardina (sin remojo) — 75 g por persona"],["840 ml","Agua o caldo de pollo (2,8 ml por gramo de lenteja)"],["400 g","Contramuslo de pollo deshuesado y sin piel"],["1 (unos 150 g)","Cebolla"],["2","Zanahorias (unos 150 g)"],["1 (unos 200 g)","Calabacín"],["1/2 (unos 100 g)","Pimiento rojo"],["2 dientes","Ajo"],["1","Tomate rallado (o 100 g triturado)"],["1 cdta","Pimentón dulce · 1 hoja de laurel"],["2 cdas (20 g)","Aceite de oliva virgen extra · sal y pimienta"]],"pasos":["DORAR: 400 g de pollo en dados con 2 cdas de aceite.","SOFRITO: 1 cebolla (unos 150 g), 1/2 pimiento rojo (unos 100 g), 2 zanahorias (unos 150 g), 2 dientes de ajo y 1 tomate. Fuera del fuego, 1 cdta de pimentón.","OLLA: 300 g de lentejas pardinas, el pollo, 1 calabacín (unos 200 g), 1 hoja de laurel, 1 cdta de sal (5 g) y 840 ml de agua o caldo. Presión alta 9 min y despresurizar 10 min.","PUNTO: el pollo a 74 °C en el centro del trozo más grande. Reposar 5 min."],"foto":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/6e/Homemade_Lentil_Soup_-_Lavash_2025-02-10.jpg/330px-Homemade_Lentil_Soup_-_Lavash_2025-02-10.jpg"}'::jsonb, 45, true),
  ('chef', 'recipe', 'bacalao-a-la-plancha-con-pisto-rapido-y-arroz-basmati', '{"n":"Bacalao a la plancha con pisto rápido y arroz basmati","pr":"Bacalao","sana":"Sí","dif":"Fácil","t":35,"val":"","com":"Haz el doble de pisto y congela la mitad: sirve para huevos, pasta o pizza. Si el lomo es muy fino (menos de 2 cm), 3 min por cada lado bastan.","cc":"Comida","rac":2,"cong":"Sí (solo el pisto)","nev":"2","tm":"No","ut":"Sartén antiadherente de 28 cm (pisto) · plancha o sartén de 24 cm (bacalao) · cazo de 18 cm con tapa (arroz) · colador · tabla y cuchillo · espátula · báscula · papel de cocina · termómetro de cocina · temporizador","ing":[["300 g (150 g por ración, crudo)","Lomos de bacalao fresco o congelado ya desalado (≈125 g cocinado por ración)"],["90 g (45 g por ración, crudo)","Arroz basmati (≈125 g cocido por ración) + 400 ml de agua para cocerlo"],["200 g","Calabacín"],["120 g","Pimiento rojo"],["80 g","Pimiento verde"],["100 g","Cebolla"],["200 g","Tomate triturado"],["1 diente","Ajo"],["20 g (2 cdas)","Aceite de oliva virgen extra: 15 g pisto + 5 g plancha (10 g por ración)"],["Al gusto","Sal, pimienta, 1 pizca de comino o pimentón; 1/2 limón"]],"pasos":["ARROZ: cocer 90 g de arroz basmati en 400 ml de agua, 10 min.","PISTO: con 15 g de aceite, 100 g de cebolla, 120 g de pimiento rojo, 80 g de pimiento verde, 1 diente de ajo, 200 g de calabacín y 200 g de tomate triturado.","PLANCHA: 300 g de bacalao con 5 g de aceite, hasta 63 °C en la parte más gruesa del lomo."],"foto":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/c3/Dorschfilet_Gem%C3%BCse_Rostock.jpg/330px-Dorschfilet_Gem%C3%BCse_Rostock.jpg"}'::jsonb, 46, true),
  ('chef', 'recipe', 'dorada-al-horno-sobre-patata-cebolla-calabacin-y-tomate', '{"n":"Dorada al horno sobre patata, cebolla, calabacín y tomate","pr":"Dorada","sana":"Sí","dif":"Fácil","t":50,"val":"","com":"Todo en una bandeja y casi sin fregar. Corta la patata fina para que esté a la vez que el pescado; el chorrito de agua o vino evita que la verdura se queme.","cc":"Cena","rac":2,"cong":"No (la patata y el pescado al horno se estropean)","nev":"1","tm":"No","ut":"Bandeja de horno de unos 30 × 40 cm (o fuente de cristal) · papel de horno · tabla y cuchillo · pelador · pincel o cuchara · espátula ancha · báscula · termómetro de cocina · temporizador","ing":[["4 lomos (≈300 g, 150 g por ración crudo)","Dorada en lomos con piel (pídela limpia en pescadería; ≈125 g cocinada por ración)"],["250 g crudo (125 g por ración)","Patata (≈125 g asada por ración)"],["200 g","Calabacín"],["150 g","Cebolla"],["40 g","Lechuga o espinacas frescas en ensalada (para servir)"],["60 g","Pimiento verde"],["2 dientes","Ajo"],["20 g (2 cdas)","Aceite de oliva virgen extra: 15 g verdura + 5 g pescado (10 g por ración)"],["1/2 + 50 ml","Limón · agua o vino blanco"],["Al gusto","Sal, pimienta, orégano o perejil seco"]],"pasos":["HORNO: precalentar a 200 °C.","BASE: 250 g de patata, 150 g de cebolla y 60 g de pimiento verde con 15 g de aceite y 50 ml de agua o vino. Después, 200 g de calabacín y el tomate.","DORADA: los 4 lomos (unos 300 g) con 5 g de aceite, 10-12 min a 200 °C, hasta 63 °C en la parte más gruesa. Servir con 40 g de lechuga o espinacas y 1/2 limón."],"foto":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/43/Gilt-head_bream_cooked_with_garnish.JPG/330px-Gilt-head_bream_cooked_with_garnish.JPG"}'::jsonb, 47, true),
  ('chef', 'recipe', 'lubina-al-vapor-con-patata-judias-verdes-y-zanahoria-varoma-tm5', '{"n":"Lubina al vapor con patata, judías verdes y zanahoria (Varoma TM5)","pr":"Lubina","sana":"Sí","dif":"Fácil","t":40,"val":"","com":"El papel mojado y arrugado evita que la piel se pegue a la bandeja. El agua del vaso sirve de caldo suave para una crema otro día. Funciona igual con merluza o dorada.","cc":"Cena","rac":2,"cong":"No","nev":"1","tm":"Sí","ut":"Thermomix TM5 con vaso, cestillo, Varoma (recipiente + bandeja) y tapa · papel de horno · tabla y cuchillo · pelador · bol pequeño para la vinagreta · báscula · termómetro de cocina","ing":[["300 g (150 g por ración, crudo)","Lomos de lubina con piel (≈125 g cocinada por ración)"],["250 g crudo (125 g por ración)","Patata (≈125 g cocida por ración)"],["250 g","Judías verdes planas (frescas o congeladas)"],["150 g","Zanahoria"],["100 g","Calabacín"],["800 ml","Agua (para el vaso)"],["20 g (2 cdas)","Aceite de oliva virgen extra, en crudo para la vinagreta (10 g por ración)"],["1/2","Limón (zumo) + unas tiras de piel"],["1 diente","Ajo picado muy fino"],["Al gusto","Sal, pimienta, perejil seco o fresco"]],"pasos":["CORTAR: 250 g de patata, 250 g de judías verdes, 150 g de zanahoria y 100 g de calabacín.","VAPOR: 800 ml de agua. Las verduras 15 min y los 300 g de lubina 12 min, hasta 63 °C en la parte más gruesa.","VINAGRETA: 20 g de aceite, el zumo de 1/2 limón y 1 diente de ajo."],"foto":"https://upload.wikimedia.org/wikipedia/commons/thumb/3/37/CHILEAN_SEA_BASS_with_SUKI_SAUCE_%28Spicy%29_Steamed_sea_bass_topped_with_our_special_spicy_chili_sauce._Served_on_top_of_steamed_vegetables.jpg/330px-CHILEAN_SEA_BASS_with_SUKI_SAUCE_%28Spicy%29_Steamed_sea_bass_topped_with_our_special_spicy_chili_sauce._Served_on_top_of_steamed_vegetables.jpg"}'::jsonb, 48, true),
  ('chef', 'recipe', 'merluza-en-salsa-verde-con-guisantes-patata-y-espinacas', '{"n":"Merluza en salsa verde con guisantes, patata y espinacas","pr":"Merluza","sana":"Sí","dif":"Fácil","t":35,"val":"","com":"El secreto de la salsa verde es mover la cazuela en círculos, no remover. Las espinacas al final le dan más color verde sin gastar más. Con almejas es de fiesta, pero no hacen falta.","cc":"Comida","rac":2,"cong":"No","nev":"1","tm":"No","ut":"Sartén honda o cazuela baja de 28 cm con tapa · tabla y cuchillo · pelador · cuchara de madera · espátula ancha · jarra medidora · báscula · termómetro de cocina · temporizador","ing":[["300 g (150 g por ración, crudo)","Merluza en rodajas o lomos de 2-3 cm (fresca o congelada; ≈125 g cocinada por ración)"],["250 g crudo (125 g por ración)","Patata (≈125 g cocida por ración)"],["150 g","Guisantes congelados"],["150 g","Espinacas frescas"],["100 g","Cebolla"],["100 g","Calabacín"],["3 dientes","Ajo"],["10 g (1 cda rasa)","Harina de trigo"],["300 ml","Caldo de pescado o de verduras (de brik) o agua"],["20 g (2 cdas)","Aceite de oliva virgen extra (10 g por ración)"],["Al gusto","Sal, perejil fresco o seco (2 cdas), 1/2 limón"]],"pasos":["SOFRITO: 20 g de aceite, 100 g de cebolla, 3 dientes de ajo y 10 g de harina.","PATATA: 300 ml de caldo, 250 g de patata y 100 g de calabacín, 12 min.","MERLUZA: 150 g de guisantes, 300 g de merluza y 150 g de espinacas, moviendo la cazuela en círculos, hasta 63 °C en la parte más gruesa."],"foto":"https://upload.wikimedia.org/wikipedia/commons/thumb/8/86/Merluza_%28salsa_verde%29.jpg/330px-Merluza_%28salsa_verde%29.jpg"}'::jsonb, 49, true),
  ('chef', 'recipe', 'brochetas-de-salmon-calabacin-y-pimiento-con-cuscus-y-ensalada-de-tomate', '{"n":"Brochetas de salmón, calabacín y pimiento con cuscús y ensalada de tomate","pr":"Salmón","sana":"Sí","dif":"Fácil","t":30,"val":"","com":"Dados grandes (3 cm) para que el salmón quede jugoso por dentro. Si no tienes palitos, haz lo mismo suelto en la sartén: 6 min removiendo con cuidado.","cc":"Cena","rac":2,"cong":"No","nev":"1","tm":"No","ut":"Sartén grill o plancha de 28 cm · 6 palitos de brocheta (de madera, remojados 10 min) · cazo de 16 cm con tapa (cuscús) · bol para ensalada · tabla y cuchillo · pinzas · tenedor · báscula · termómetro de cocina · temporizador","ing":[["300 g (150 g por ración, crudo)","Lomo de salmón sin piel (≈125 g cocinado por ración)"],["90 g crudo (45 g por ración)","Cuscús (≈125 g hidratado por ración) + 110 ml de agua hirviendo"],["150 g","Calabacín"],["100 g","Pimiento rojo"],["50 g","Cebolla roja o normal"],["150 g","Tomate"],["50 g","Pepino"],["20 g (2 cdas)","Aceite de oliva virgen extra: 5 g plancha + 15 g en crudo (10 g por ración)"],["1","Limón (zumo y unas rodajas)"],["Al gusto","Sal, pimienta, comino o pimentón dulce, perejil"]],"pasos":["MONTAR: 300 g de salmón en dados, 150 g de calabacín, 100 g de pimiento rojo y 50 g de cebolla.","CUSCÚS: 90 g de cuscús con 110 ml de agua hirviendo.","PLANCHA: con 5 g de aceite, hasta 63 °C en el centro del dado más grueso.","ENSALADA: 150 g de tomate y 50 g de pepino con 15 g de aceite y el zumo de 1 limón."],"foto":"https://upload.wikimedia.org/wikipedia/commons/thumb/1/10/Salmon_kebabs.jpg/330px-Salmon_kebabs.jpg"}'::jsonb, 50, true),
  ('chef', 'recipe', 'cogollos-a-la-plancha-con-ajo-dorado-pimenton-y-limon', '{"n":"Cogollos a la plancha con ajo dorado, pimentón y limón","pr":"Cogollo","sana":"Sí","dif":"Fácil","t":15,"val":"","com":"El contraste caliente-tostado por fuera y crujiente-frío por dentro es la gracia. Variante: unas anchoas o un poco de queso rallado encima; o vinagre de Módena en vez de limón.","cc":"Cena","rac":2,"cong":"No (la lechuga se deshace)","nev":"0 (al momento; el aliño aparte aguanta 3 días)","tm":"No","ut":"Plancha o sartén antiadherente de 28 cm · sartén pequeña o cazo de 16 cm (ajos) · tabla y cuchillo · bol pequeño · pinzas o espátula · cuchara · papel de cocina · temporizador","ing":[["4 (unos 400 g)","Cogollos de Tudela (1 paquete de Ahorramás)"],["30 g (3 cdas)","Aceite de oliva virgen extra: 10 g plancha + 20 g aliño"],["3 dientes","Ajo"],["1/2 cdta (2 g)","Pimentón dulce de la Vera (o la mitad picante)"],["1 pizca (0,5 g)","Comino molido"],["1/2","Limón (zumo, unos 15 ml) o 1 cda de vinagre de Jerez"],["1 pizca","Sal en escamas (o sal normal)"],["1 cda (opcional)","Pipas de girasol peladas o pan rallado tostado, para el crujiente"]],"pasos":["AJOS: 3 dientes de ajo en 20 g de aceite, hasta que estén dorado claro.","ALIÑO: 1/2 cdta de pimentón, 1 pizca de comino y el zumo de 1/2 limón (unos 15 ml).","PLANCHA: los 4 cogollos (unos 400 g) con 10 g de aceite, la cara cortada hacia abajo, hasta que dore y el centro siga crujiente."],"foto":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/6b/Grilled_romaine.jpg/330px-Grilled_romaine.jpg"}'::jsonb, 51, true),
  ('chef', 'recipe', 'tortilla-de-patatas-con-patatas-fritas-de-bolsa-chips', '{"n":"Tortilla de patatas con patatas fritas de bolsa (chips)","pr":"Huevo","sana":"Moderado","dif":"Fácil","t":21,"val":"","com":"El truco del reposo: 8 minutos en el huevo y las patatas quedan blandas como en la tortilla de siempre, en 20 minutos y sin freír. Usa patatas lisas clásicas y no sales la mezcla.","cc":"Cena","rac":2,"cong":"No (el huevo cuajado queda gomoso)","nev":"2","tm":"No","ut":"Sartén antiadherente de 20 cm (con mango largo) · bol grande · tenedor o varillas · plato llano más ancho que la sartén (unos 26 cm) · espátula de silicona · paño seco o manopla · termómetro de cocina · temporizador","ing":[["4 (talla L, unos 240 g sin cáscara)","Huevos"],["100 g (1 bolsa pequeña)","Patatas fritas de bolsa, clásicas lisas y con sal (no onduladas ni de sabores)"],["10 g (1 cda)","Aceite de oliva virgen extra (para la sartén)"],["SIN sal añadida","Las patatas ya llevan sal suficiente; prueba antes de añadir"],["Opcional: 1 pizca","Pimienta negra o perejil picado"]],"pasos":["BATIR: los 4 huevos (unos 240 g sin cáscara) hasta mezclar yema y clara.","HIDRATAR: 100 g de patatas fritas de bolsa, en trozos, dentro del huevo. Reposar 8 min, sin añadir sal.","CUAJAR: sartén con 10 g de aceite. Primera cara y dar la vuelta.","PUNTO: 71 °C en el centro de la tortilla. Reposar 2 min y cortar en 4 trozos."],"foto":"https://upload.wikimedia.org/wikipedia/commons/thumb/b/b1/Tortilla_Espa%C3%B1ola.jpg/330px-Tortilla_Espa%C3%B1ola.jpg"}'::jsonb, 52, true),
